comms.text:
@1 דַיָנִין וּפֻרְעָנִין תְּמַנֵי לָךְ בְּכֹל קִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְשִׁבְטָיךְ וִידוּנוּן יָת עַמָא דִין דִקְשׁוֹט:
@2 לָא תַצְלֵי דִין לָא תִשְׁתְּמוֹדַע אַפִּין וְלָא תְקַבֵּל שֹׁחֲדָא אֲרֵי שֹׁחֲדָא מְעַוֵּר עֵינֵי חַכִּימִין וּמְקַלְקַל פִּתְגָמִין תְּרִיצִין:
@3 קֻשְׁטָא קֻשְׁטָא תְּהֵי רָדִיף בְּדִיל דְתֵיחֵי וְתֵירַת יָת אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@4 לָא תִצוֹב לָךְ אֲשֵׁרַת כָּל אִילָן בִּסְטַר מַדְבְּחָא דַיְיָ אֱלָהָךְ דִי תַעְבֶּד לָךְ:
@5 וְלָא תְקִים לָךְ קָמָא דִי סָנֵי יְיָ אֱלָהָךְ:
@6 לָא תִכּוֹס קֳדָם יְיָ אֱלָהָךְ תּוֹר וְאִמָר דִי יְהֵי בֵהּ מוּמָא כֹּל מִדַעַם בִּישׁ אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ הוּא:
@7 אֲרֵי יִשְׁתְּכַח בֵּינָךְ בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ גְבַר אוֹ אִתְּתָא דִי יַעְבֵּד יָת דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְמֶעְבַּר עַל קְיָמֵהּ:
@8 וַאֲזַל וּפְלַח לְטַעֲוַת עַמְמַיָא וּסְגִיד לְהוֹן וּלְשִׁמְשָׁא אוֹ לְסִיהֲרָא אוֹ לְכָל חֵילֵי שְׁמַיָא דִי לָא פַקֵדִית:
@9 וְיִתְחַוֵי לָךְ וְתִשְׁמַע וְתִתְבַּע יָאוּת וְהָא קֻשְׁטָא כֵּוַן פִּתְגָמָא אִתְעֲבִידַת תּוֹעֶבְתָּא הָדָא בְּיִשְׂרָאֵל:
@10 וְתַפֵּק יָת גַבְרָא הַהוּא אוֹ יָת אִתְּתָא הַהִיא דִי עֲבָדוּ יָת פִּתְגָמָא בִישָׁא הָדֵין לִתְרַע בֵּית דִינָךְ יָת גַבְרָא אוֹ יָת אִתְּתָא וְתִרְגְמִנוּן בְּאַבְנַיָא וִימוּתוּן:
@11 עַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקְטִל דְחַיַב קְטוֹל לָא יִתְקְטֵל עַל מֵימַר סָהִיד חָד:
@12 יְדָא דְסַהֲדַיָא תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְּבַתְרֵיתָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@13 אֲרֵי יִתְכַסֵי מִנָךְ פִּתְגָמָא לְדִינָא בֵּין דְמָא לִדְמָא בֵּין דִינָא לְדִינָא וּבֵין מַכְתַּשׁ סְגִירוּ לְמַכְתַּשׁ סְגִירוּ פִּתְגָמֵי פְלֻגְתָּא דִינָא בְּקִרְוָיךְ וּתְקוּם וְתִסַק לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@14 וְתֵיתֵי לְוָת כָּהֲנַיָא לֵוָאֵי וּלְוָת דַיָנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתִתְבַּע וִיחַוּוּן לָךְ יָת פִּתְגָמָא דְדִינָא:
@15 וְתַעְבֵּד עַל מֵימַר פִּתְגָמָא דִי יְחַוּוּן לָךְ מִן אַתְרָא הַהוּא דִי יִתִּרְעֵי יְיָ וְתִטַר לְמֶעְבַּד כְּכֹל דִי יַלְפֻנָךְ:
@16 עַל מֵימַר אוֹרַיְתָא דִי יַלְפֻנָךְ וְעַל דִינָא דִי יֵימְרוּן לָךְ תַּעְבֵּד לָא תִסְטֵּי מִן פִּתְגָמָא דִי יְחַוּוּן לָךְ יַמִינָא וּשְׂמָאלָא:
@17 וּגְבַר דִי יַעְבֵּד בִּרְשַׁע בְּדִיל דְלָא לְקַבָּלָא מִן כַּהֲנָא דְקָאֵם לְשַׁמָשָׁא תַמָן קֳדָם יְיָ אֱלָהָךְ אוֹ מִן דַיָנָא וְיִתְקְטֵל גַבְרָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@18 וְכָל עַמָא יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יַרְשִׁיעוּן עוֹד:
@19 אֲרֵי תֵעוֹל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וְתֵירְתַהּ וְתֵיתֵב בַּהּ וְתֵימַר אֱמַנִי עֲלַי מַלְכָּא כְּכָל עַמְמַיָא דִי בְסַחֲרָנָי:
@20 מַנָאָה תְמַנֵי עֲלָךְ מַלְכָּא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ מִגוֹ אַחָיךְ תְּמַנֵי עֲלָךְ מַלְכָּא לֵת לָךְ רְשׁוּ לְמַנָאָה עֲלָךְ גְבַר נוּכְרַי דִי לָא אֲחוּךְ הוּא:
@21 לְחוֹד לָא יַסְגֵי לֵהּ סוּסָוָן וְלָא יָתֵב יָת עַמָא לְמִצְרָיִם בְּדִיל לְאַסְגָּאָה לֵהּ סוּסָוָן וַיְיָ אֲמַר לְכוֹן לָא תוֹסְפוּן לְמִתוּב בְּאֹרַח הָדֵין עוֹד:
@22 וְלָא יַסְגֵי לֵהּ נְשִׁין וְלָא יִטְעֵי לִבֵּהּ וְכַסְפָּא וְדַהַבָא לָא יַסגֵי לֵהּ לַחֲדָא:
@23 וִיהֵי:כְמִתְּבֵהּ עַל כָּרְסָא מַלְכוּתֵהּ וְיִכְתּוֹב לֵהּ יָת פַּתְשֶׁגֶן אוֹרַיְתָא הָדָא עַל סִפְרָא מִן קֳדָם כָּהֲנַיָא לֵוָאֵי:
@24 וּתְהֵי עִמֵהּ וִיהֵי קָרֵי בֵהּ כָּל יוֹמֵי חַיוֹהִי בְּדִיל דְיֵלַף לְמִדְחַל קֳדָם יְיָ אֱלָהֵהּ לְמִטַּר יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא וְיָת קְיָמַיָא הָאִלֵין לְמֶעְבָּדְהוֹן:
@25 בְּדִיל דְלָא יְרִים לִבֵּהּ מֵאֲחוֹהִי וּבְדִיל דְלָא יִסְטֵּי מִן תַּפְקֶדְתָּא יַמִינָא וּשְׂמָאלָא בְּדִיל דְיוֹרֵךְ יוֹמִין עַל מַלְכוּתֵהּ הוּא וּבְנוֹהִי בְּגוֹ יִשְׂרָאֵל:
@26 לָא יְהֵי לְכָהֲנַיָא לֵוָאֵי כָּל שִׁבְטָא דְלֵוִי חֳלָק וְאַחֲסָנָא עִם יִשְׂרָאֵל קֻרְבָּנַיָא דַיְיָ וְאַחֲסַנְתֵּהּ יֵיכְלוּן:
@27 וְאַחֲסָנָא לָא יְהֵי לֵהּ בְּגוֹ אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל לֵהּ:
@28 וְדֵין יְהֵי דְחָזֵי לְכָהֲנַיָא מִן עַמָא מִן נָכְסֵי נִכְסָתָא אִם תּוֹר אִם אִמָר וְיִתֵּן לְכַהֲנָא דְרוֹעָא וְלוֹעָא וְקֻבְתָא:
@29 רֵישׁ עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וְרֵישׁ גִזָא דְעָנָךְ תַּפְרֵשׁ לֵהּ:
@30 אֲרֵי בֵהּ יִתִּרְעֵי יְיָ אֱלָהָךְ מִכָּל שִׁבְטָיךְ לְמֵקַם לְשַׁמָשָׁא בִשְׁמָא דַיְיָ הוּא וּבְנוֹהִי כָּל יוֹמַיָא:
@31 וַאֲרֵי יֵיתֵי לֵוָאָה מֵחֲדָא מִקִרְוָיךְ מִכָּל יִשְׂרָאֵל דִי הוּא דָר תַּמָן וְיֵיתֵי בְּכָל רְעוּת נַפְשֵׁהּ לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@32 וִישַׁמַשׁ בִּשְׁמָא דַיְיָ אֱלָהֵהּ כְּכָל אֲחוֹהִי לֵוָאֵי דִמְשַׁמְשִׁין תַּמָן (בִּצְלוֹ) קֳדָם יְיָ:
@33 חֳלָק כָּחֳלָק יֵיכְלוּן בַּר מִמַטַרְתָּא דְיֵיתֵי בְּשַׁבַּתָּא דְכֵן אַתְקִינוּ אֲבָהָתָא:
@34 אֲרֵי אַתְּ עָלֵל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תֵילַף לְמֶעְבַּד כְּתֹעֲבַת עַמְמַיָא הָאִנוּן:
@35 לָא יִשְׁתְּכַח בָּךְ מַעֲבַר בְּרֵהּ וּבְרַתֵּהּ בְּנוּרָא קָסֵם קֻסְמִין מְעָנֵן וּמְנַחֵשׁ וְחָרָשׁ:
@36 וְרָטִין רְטָן וְשָׁאֵל בִּדִין וּדְכוּרוּ וְתָבַע מִן מֵתַיָא:
@37 אֲרֵי מְרָחָק יְיָ כָּל דְיַעְבֵּד אִלֵין וּבְדִיל תּוֹעֲבָתָא הָאִלֵין יְיָ אֱלָהָךְ מְתָרַךְ יָתְהוֹן מִקֳדָמָךְ:
@38 שְׁלִים תְּהֵי בְּדַחַלְתָּא דַיְיָ אֱלָהָךְ:
@39 אֲרֵי עַמְמַיָא הָאִלֵין דִי אַתְּ יָרֵת יָתְהוֹן מִן מְעָנְנַיָא וּמִן קַסָמַיָא שָׁמְעִין וְאַתְּ לָא כֵן יְהַב לָךְ יְיָ אֱלָהָךְ:
@40 נְבִיָא מִבֵּינָךְ מֵאַחָיךְ כְּוָתִי יְקִים לָךְ יְיָ אֱלָהָךְ מִנֵהּ תְּקַבְּלוּן:
@41 כְּכֹל דִי שְׁאֶלְתָּא מִקֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב בְּיוֹמָא דִקְהָלָא לְמֵימָר לָא אוֹסֵף לְמִשְׁמָע יָת קָל מֵימְרָא דַיְיָ אֱלָהַי וְיָת אֶשָׁתָא רַבְּתָא הָדָא לָא אֶחֱזֵי עוֹד וְלָא אֵמוּת:
@42 וַאֲמַר יְיָ לִי אוֹטִיבוּ דִי מַלִילוּ:
@43 נְבִיָא אֲקִים לְהוֹן מִגוֹ אֲחֵיהוֹן כְּוָתָךְ וְאֶתֵּן פִּתְגָמֵי נְבוּאָתִי בְּפוּמֵהּ וִימַלֵל עִמְהוֹן יָת כָּל דִי אֲפַקְדִנֵהּ:
@44 וִיהֵי גַבְרָא דִי לָא יְקַבֵּל לְפִתְגָמַי דִי יְמַלֵל בִּשְׁמִי מֵימְרִי יִתְבַּע מִנֵהּ:
@45 בְּרַם נְבִיָא דִי יַרְשַׁע לְמַלָלָא פִתְגָמָא בִּשְׁמִי יָת דִי לָא פַקֵדִתֵּה לְמַלָלָא וְדִי יְמַלֵיל בְּשׁוּם טַעֲוַת עַמְמַיָא וְיִתְקְטֵל נְבִיָא הַהוּא:
@46 וַאֲרֵי תֵימַר בְּלִבָּךְ אֶכְדֵן נִדַע יָת פִּתְגָמָא דִי לָא מַלְלֵהּ יְיָ:
@47 דִי יְמַלֵל נְבִיָא בִּשְׁמָא דַיְיָ וְלָא יְהֵי פִתְגָמָא וְלָא יִתְקַיַם הוּא פִתְגָמָא דִי לָא מַלְלֵהּ יְיָ בִּרְשַׁע מַלְלֵהּ נְבִיָא לָא תִדְחַלּ מִנֵהּ:
@48 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעֲהוֹן וְתֵרְתִנוּן וְתֵיתֵב בְּקִרְוֵיהוֹן וּבְבָתֵּיהוֹן:
@49 תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@50 תְּתַקֵן לָךְ אָרְחָא וּתְתַלַת יָת תְּחוּם אַרְעָךְ דִי יַחְסְנִנָךְ יְיָ אֱלָהָךְ וִיהֵי לְמֵעִירוֹק תַּמָן כָּל קָטוֹלָא:
@51 וְדֵין פִּתְגַם קָטוֹלָא דְיֵעִרוֹק תַּמָן וְיִתְקַיַם דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵהּ וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקָמוֹהִי:
@52 וְדִי יֵעוֹל עִם חַבְרֵהּ בְּחֻרְשָׁא לְמִקַץ אָעִין וְתִתְמְרֵיג יְדֵהּ בְּפַרְזְלָא לְמִקַץ אָעָא וְיִשְׁתְּלֵף פַּרְזְלָא מִן אָעָא וְיַשְׁכַּח יָת חַבְרֵהּ וִימוּת הוּא יֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין וְיִתְקַיַם:
@53 דִילְמָא יִרְדוֹף גָאֵל דְמָא בָּתַר קָטוֹלָא אֲרֵי יֵחַם לִבֵּה וְיַדְבְּקִנֵהּ אֲרֵי תִסְגֵי אָרְחָא וְיִקְטְלִנֵהּ נְפַשׁ וְלֵהּ לֵית חוֹבַת דִין דִקְטוֹל אֲרֵי לָא סָנֵי הוּא לֵהּ מִתְּמַלֵי וּמִדְקָמוֹהִי:
@54 עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימָר תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ:
@55 וְאִם יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ וְיִתֶּן לָךְ יָת כָּל אַרְעָא דִי מַלִיל לְמִתַּן לַאֲבָהָתָךְ:
@56 אֲרֵי תִטַר יָת כָּל תַּפְקֶדְתָּא הָדָא לְמֶעְבְּדַהּ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ וְלִמְהַךְ בְּאָרְחָן דְתַקְנָן קֳדָמוֹהִי כָּל יוֹמַיָא וְתוֹסֵף לָךְ עוֹד תְּלַת קִרְוִין עַל תְּלַת אִלֵין:
@57 וְלָא יִשְׁתְּפֵךְ דָם זַכַּי בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וִיהֵי עֲלָךְ חוֹבַת דִין דִקְטוֹל:
@58 וַאֲרֵי יְהֵי גְבַר סָנֵי לְחַבְרֵהּ וְיִכְמַן לֵהּ וִיקוּם עֲלוֹהִי וְיִמְחִנֵהּ נְפָשׁ וִימוּת וְיֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין:
@59 וִישַׁלְחוּן סָבֵי קַרְתֵּהּ וְיִדְבְּרוּן יָתֵהּ מִתַּמָן וְיִתְּנוּן יָתֵהּ בְּיַד גָאֵל דְמָא וִימוּת:
@60 לָא תְחוּס עֵינָךְ עֲלוֹהִי וּתְפַלֵי אַשְׁדִי דָם זַכַּי מִיִשְׂרָאֵל וְיֵיטַב לָךְ:
@61 לָא תַשְׁנֵי תְּחוּמָא דְחַבְרָךְ דִי תְחִימוּ קַדְמָאֵי בְּאַחֲסַנְתָּךְ דִי תַחֲסֵן בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@62 לָא יְקוּם סָהִיד חַד בִּגְבַר לְכָל עַוָיָן וּלְכָל חוֹבִין בְּכָל חֵט דִי יֶחְטֵי עַל מֵימַר תְּרֵין סָהֲדִין אוֹ עַל מֵימַר תְּלָתָא סָהֲדִין יִתְקַיַם פִּתְגָמָא:
@63 אֲרֵי יְקוּם סָהִיד שְׁקַר בִּגְבָר לְאַסְהָדָא בֵהּ סַטְּיָא:
@64 וִיקוּמוּן תְרֵין גֻבְרִין דִי לְהוֹן דִינָא קֳדָם יְיָ קֳדָם כָּהֲנַיָא וְדַיָנַיָא דִי יְהוֹן בְּיוֹמַיָא הָאִנוּן:
@65 וְיִתְבְּעוּן דַיָנַיָא יָאוּת וְהָא סָהִיד שְׁקַר סָהֲדָא שִׁקְרָא אַסְהַד בַּאֲחוֹהִי:
@66 וְתַעְבְּדוּן לֵהּ כְּמָא דִי חַשִׁיב לְמֶעְבַּד לַאֲחוֹהִי וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@67 וּדְיִשְׁתַּאֲרוּן יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד עוֹד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@68 וְלָא תְחוּס עֵינָךְ נַפְשָׁא חֳלַף נַפְשָׁא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא יְדָא חֳלַף יְדָא רַגְלָא חֳלַף רַגְלָא:
@69 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְתֶחֱזֵי סוּסָוָן וּרְתִכִּין עַם סַגִי מִנָךְ לָא תִדְחַל מִנְהוֹן אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ בְּסַעְדָךְ דְאַסְקָךְ מֵאַרְעָא דְמִצְרָיִם:
@70 וִיהֵי כְּמִקְרָבְכוֹן לַאֲגָחָא קְרָבָא וְיִתְקְרִיב כַּהֲנָא וִימַלֵל עִם עַמָא:
@71 וְיֵימַר לְהוֹן שְׁמַע יִשְׂרָאֵל אַתּוּן קְרִיבִין יוֹמָא דֵין לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן לָא יְזוּעַ לִבְּכוֹן לָא תִדְחֲלוּן וְלָא תִתְבַּהֲתוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן:
@72 אֲרֵי יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן לַאֲגָחָא לְכוֹן קְרָב עִם בַּעֲלֵי דְבָבֵיכוֹן לְמִפְרַק יָתְכוֹן:
@73 וִימַלְלוּן סָרְכַיָא קֳדָם עַמָא לְמֵימָר מָן גַבְרָא דִי בְנָא בֵיתָא חַדְתָּא וְלָא חָנְכֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יַחְנְכִנֵהּ:
@74 וּמָן גַבְרָא דִי נְצִיב כַּרְמָא וְלָא אַחֲלֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יְחַלִנֵהּ:
@75 וּמָן גַבְרָא דִי אֵרַס אִתְּתָא וְלָא נָסְבַהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחֳרָן יִסְבִנַהּ:
@76 וְיוֹסְפוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וְיֵימְרוּן מָן גַבְרָא דְדָחֵל וּתְבִיר לִבָּא יְהַךְ וִיתוּב לְבֵיתֵהּ וְלָא יִתְּבַר יָת לִבָּא דַאַחוֹהִי כְּלִבֵּהּ:
@77 וִיהֵי כַּד יְשֵׁצוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וִימַנוּן רַבָּנֵי חֵילָא בְּרֵישׁ עַמָא:
@78 אֲרֵי תִקְרַב לְקַרְתָּא לַאֲגָחָא (קְרָבָא) עֲלַהּ וְתִקְרֵי לַהּ מִלִין דִשְׁלָם:
@79 וִיהֵי אִם שְׁלַם תַּעֲנִנָךְ וְתִפְתַּח לָךְ וִיהֵי כָּל עַמָא דְיִשְׁתְּכַח בַּהּ יְהוֹן לָךְ מַסְקֵי מִסִין וְיִפְלְחֻנָךְ:
@80 וְאִם לָא תַשְׁלֵם עִמָךְ וְתַעְבֵּד עִמָךְ קְרָב וּתְצוּר עֲלַהּ:
@81 וְיִמְסְרִנַהּ יְיָ אֱלָהָךְ בִּידָךְ וְתִמְחֵי יָת כָּל דְכוּרַהּ לְפִתְגַם דְחָרֶב:
@82 לְחוֹד נְשַׁיָא וְטַפְלָא וּבְעִירָא וְכֹל דִי יְהֵי בְקַרְתָּא כָּל עֲדָאַהּ תֵּבוֹז לָךְ וְתֵיכוּל יָת עֲדָאָה דְסַנְאָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@83 כֵּן תַּעְבֵד לְכָל קִרְוַיָא דִי רְחִיקִין מִנָךְ לַחֲדָא דִי לָא מִקִרְוֵי עַמְמַיָא הָאִלֵין אִנוּן:
@84 לְחוֹד מִקִרְוֵי עַמְמַיָא הָאִלֵין דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לָא תְקַיַם כָּל נִשְׁמָתָא:
@85 אֲרֵי גַמָרָא תְגַמְרִנוּן חִתָּאֵי וֶאֱמֹרָאֵי כְּנַעֲנָאֵי וּפְרִזָאֵי חִוָאֵי וִיבוּסָאֵי כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@86 בְּדִיל דִי לָא יַלְפוּן יָתְכוֹן לְמֶעְבַּד כְּכָל תּוֹעֲבָתְהוֹן דִי עֲבָדוּ לְטַעֲוָתְהוֹן וּתְחוֹבוּן קֳדָם יְיָ אֱלָהֲכוֹן:
@87 אֲרֵי תְצוּר לְקַרְתָּא יוֹמִין סַגִיאִין לַאֲגָחָא עֲלַהּ לְמִכְבְּשַׁהּ לָא תְחַבֵּל יָת אִילָנַהּ לַאֲרָמָא עֲלוֹהִי פַּרְזְלָא אֲרֵי מִנֵה תֵּיכוּל וְיָתֵהּ לָא תְקוּץ אֲרֵי לָא כַאֲנָשָׁא אִילַן חַקְלָא לְמֵיעַל מְקָדָמָךְ בִּצְיָרָא:
@88 לְחוֹד אִילָן דְתִדַע אֲרֵי לָא אִילַן דְמַאֲכָל הוּא יָתֵהּ תְּחַבַּל וּתְקוּץ וְתִבְנֵי כַרְקוֹמִין עַל קַרְתָּא דִי הִיא עָבְדָא עִמָךְ קְרָבָא עַד דְתִכְבְּשַׁהּ:
@89 אֲרֵי יִשְׁתְּכַח קְטִּילָא בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ רָמֵי בְּחַקְלָא לָא אִתְיְדַע מַן קָטְּלֵהּ:
@90 וְיִפְּקוּן סָבָיךְ וְדַיָנָיךְ וְיִמְשְׁחוּן לְקִרְוַיָא דִי סַחֲרָנוּת קְטִילָא:
@91 וּתְהֵי קַרְתָּא דִקְרִיבָא לִקְטִילָא וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא עֶגְלַת תּוֹרֵי דִי לָא אִתְפְּלַח בַּהּ דִי לָא נְגִידַת בְּנוּר:
@92 וְיֶחֱתוּן סָבֵי קַרְתָּא הַהִיא יָת עֲגַלְתָּא לְנַחֲלָא בַיָר דִי לָא יִתְפְּלַח בֵּהּ וְלָא יִזְדְרַע וְיִנְקְפוּן תַּמָן יָת עֲגַלְתָּא בְּנַחֲלָא:
@93 וְיִתְקָרְבוּן כָּהֲנַיָא בְּנֵי לֵוִי אֲרֵי בְהוֹן יִתִּרְעֵי יְיָ אֱלָהָךְ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִּשְׁמָא דַיְיָ וְעַל מֵימְרֵהוֹן יְהֵי כָּל דִין וְכָל מַכְתַּשׁ סְגִירוּ:
@94 וְכֹל סָבֵי קַרְתָּא הַהִיא דִקְרִיבִין לִקְטִילָא יַסְחוּן יָת יְדֵיהוֹן עַל עֲגַלְתָּא דִנְקֶפְתָּא בְנַחֲלָא:
@95 וִיתִיבוּן וְיֵימְרוּן יְדָנָא לָא אַשְׁדוֹ יָת דְמָא הָדֵין וְעֵינָנָא לָא חֲזָאָה:
@96 כָּהֲנַיָא יֵימְרוּן כַּפַּר לְעַמָךְ יִשְׂרָאֵל דִי פְרַקְתָּא יְיָ וְלָא תִתֵּן חוֹבַת דַם זַכַּי בְּגוֹ עַמָךְ יִשְׂרָאֵל וְיִתְכַּפַּר לְהוֹן עַל דְמָא:
@97 וְאַתְּ תְּפַלֵי אַשְׁדִי דַם זַכַּי מִבֵּינָךְ אֲרֵי תַעְבֵּד דְכָשַׁר קֳדָם יְיָ: ססס:

@1 **שפטים ושטרים.** שופטים, דינים הפוסקים את הדין. ושוטרים, הרודין את העם אחר מצותם. שמכין וכופתין במקל וברצועה עד שיקבל עליו את דין השופט: **בכל שעריך.** בכל עיר ועיר: **לשבטיך.** מוסב על תתן לך. שופטים ושוטרים תתן לך לשבטיך בכל שעריך אשר ה' אלהיך נתן לך: **לשבטיך.** מלמד שמושיבין דינין לכל שבט ושבט ובכל עיר ועיר: **ושפטו את העם** וגו' **.** מנה דינין מומחים וצדיקים לשפוט צדק:
@2 **לא תטה משפט.** כמשמעו: **לא תכיר פנים.** אף בשעת הטענות. אזהרה לדין שלא יהא רך לזה וקשה לזה, אחד עומד ואחד יושב. לפי שכשרואה שהדין מכבד את חברו מסתתמין טענותיו: **ולא תקח שחד.** אפלו לשפוט צדק: **כי השחד יעור.** משקבל שחד ממנו אי אפשר שלא יטה את לבו אצלו להפוך בזכותו: **דברי צדיקים.** דברים המצדקים, משפטי אמת:
@3 **צדק צדק תרדף.** הלך אחר בית דין יפה: **למען תחיה וירשת.** כדאי הוא מנוי הדינין הכשרים להחיות את ישראל ולהושיבן על אדמתן:
@4 **לא תטע לך אשרה.** לחייבו עליה משעת נטיעתה ואפלו לא עבדה עובר בלא תעשה על נטיעתה: **לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך.** אזהרה לנוטע אילן ולבונה בית בהר הבית:
@5 **ולא תקים לך מצבה.** מצבת אבן אחת, להקריב עליה אפלו לשמים: **אשר שנא.** מזבח אבנים ומזבח אדמה צוה לעשות, ואת זו שנא כי חק היתה לכנענים. ואף על פי שהיתה אהובה לו בימי האבות, עכשיו שנאה, מאחר שעשאוה אלו חק לעבודה זרה:
@6 **לא תזבח** וגו' **כל דבר רע.** אזהרה למפגל בקדשים על ידי דבור רע. ועוד נדרשו בו שאר דרשות בשחיטת קדשים:
@7 **לעבר בריתו.** אשר כרת אתכם שלא לעבוד עבודה זרה:
@8 **אשר לא צויתי.** לעבדם:
@9 **נכון.** מכון העדות:
@10 **והוצאת את האיש ההוא:. אל שעריך** וגו' **.** המתרגם אל שעריך, לתרע בית דינך, טועה, שכן שנינו אל שעריך זה שער שעבד בו, או אינו אלא שער שנדון בו, נאמר שעריך למטה ונאמר שעריך למעלה (פסוק ב) מה שעריך האמור למעלה שער שעבד בו אף שעריך האמור למטה שער שעבד בו. ותרגומו לקרוך:
@11 **שנים [עדים] או שלשה.** אם מתקימת עדות בשנים למה פרט לך בשלשה, להקיש שלשה לשנים, מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כלם:
@13 **כי יפלא.** כל הפלאה לשון הבדלה ופרישה, שהדבר נבדל ומכסה ממך: **בין דם לדם.** בין דם טמא לדם טהור: **בין דין לדין.** בין דין זכאי לדין חיב: **בין נגע לנגע.** בין נגע טמא לנגע טהור: **דברי ריבת.** שיהו חכמי העיר חולקים בדבר, זה מטמא וזה מטהר זה מחיב וזה מזכה: **וקמת ועלית.** מלמד שבית המקדש גבוה מכל המקומות:
@14 **הכהנים הלוים.** הכהנים שיצאו משבט לוי: **ואל השפט אשר יהיה בימים ההם.** ואפלו אינו כשאר שופטים שהיו לפניו אתה צריך לשמוע לו. אין לך אלא שופט שבימיך:
@16 **ימין ושמאל.** אפלו אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין, וכל שכן שאומר לך על ימין ימין ועל שמאל שמאל:
@18 **וכל העם ישמעו.** מכאן שממתינין לו עד הרגל וממיתין אותו ברגל:
@21 **לא ירבה לו סוסים.** אלא כדי מרכבתו, שלא ישיב את העם מצרימה, שהסוסים באים משם. כמה שנאמר בשלמה, ותעלה ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה (מלכים א' י, כט) :
@22 **ולא ירבה לו נשים.** אלא שמונה עשרה, שמצינו שהיו לו לדוד שש נשים, ונאמר לו ואם מעט ואספה לך כהנה וכהנה (שמואל ב' יב, ח) : **וכסף וזהב לא ירבה לו מאד.** אלא כדי לתן לאכסניא [לאפסניא] :
@23 **והיה כשבתו.** אם עשה כן, כדאי הוא שתתקיים מלכותו: **את משנה התורה.** שתי ספרי תורה. אחת שהיא מנחת בבית גנזיו ואחת שנכנסת ויוצאת עמו. ואונקלוס תרגם פתשגן, פתר משנה לשון שנון ודבור:
@24 **דברי התורה.** כמשמעו:
@25 **ולבלתי סור מן המצוה.** אפלו מצוה קלה של נביא: **למען יאריך ימים.** מכלל הן אתה שומע לאו. וכן מצינו בשאול שאמר לו שמואל שבעת ימים תוחל עד בואי אליך להעלות עלות (שמואל א' י, ח) וכתיב ויוחל שבעת ימים (שמואל א' יג, ח) ולא שמר הבטחתו לשמור כל היום, ולא הספיק להעלות העולה עד שבא שמואל ואמר לו נסכלת לא שמרת וגו' ועתה ממלכתך לא תקום (שם יג ז. יד) . הא למדת, שבשביל מצוה קלה של נביא נענש: **הוא ובניו.** מגיד שאם בנו הגון למלכות הוא קודם לכל אדם:
@27 **כל שבט לוי.** בין תמימין בין בעלי מומין: **חלק.** בבזה: **ונחלה.** בארץ: **אשי ה'.** קדשי המקדש [הקדשים] : **ונחלתו.** אלו קדשי הגבול תרומות ומעשרות. אבל נחלה גמורה לא יהיה לו בקרב אחיו. ובספרי דרשו, ונחלה לא יהיה לו. זו נחלת שאר: **בקרב אחיו.** זו נחלת חמשה. ואיני יודע מה היא. ונראה לי שארץ כנען שמעבר הירדן ואלך נקראת ארץ חמשה עממין, ושל סיחון ועוג, שני עממין אמורי וכנעני. ונחלת שאר לרבות קיני וקנזי וקדמוני. וכן דורש בפרשת מתנות שנאמרו לאהרן על כן לא היה ללוי וגו' (דברים י, ט) להזהיר על קיני וקנזי וקדמוני. שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי ונחלה לא יהיה לו אלו נחלת חמשה. בקרב אחיו אלו נחלת שבעה. נחלת חמשה שבטים ונחלת שבעה שבטים. ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד, שכן משה הנחיל לראובן וגד וחצי שבט מנשה, ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה, ושבעה האחרים נטלו מאליהן אחרי מות יהושע, מתוך כך הזכיר חמשה לבד ושבעה לבד: **כאשר דבר לו.** לאהרן, בארצם לא תנחל וגו' אני חלקך (במדבר יח, כ) :
@28 **מאת העם.** ולא מאת הכהנים: **אם שור אם שה.** פרט לחיה: **הזרוע.** מן הפרק של ארכבה עד כף של יד שקורין אשפלדו''ן [עצם השכם] : **והלחיים.** עם הלשון. דורשי רשומות היו אומרים, זרוע, תחת יד, שנאמר (במדבר כה, ז) ויקח רמח בידו. לחיים, תחת תפלה, שנאמר (תהל' קו, ל) ויעמד פינחס ויפלל: **והקבה.** תחת (במד' כה) האשה אל קבתה:
@29 **ראשית דגנך.** זו תרומה, ולא פרש בה שעור, אבל רבותינו נתנו בה שעור, עין יפה אחד מארבעים, עין רעה אחד מששים, בינונית אחד מחמשים. וסמכו על המקרא שלא לפחות מאחד מששים, שנאמר וששיתם האיפה מחמר השערים (יחזקאל מה, יג) ששית האיפה, חצי סאה. כשאתה נותן חצי סאה לכור, הרי אחד מששים, שהכור שלשים סאין: **וראשית גז צאנך.** כשאתה גוזז צאנך בכל שנה תן ממנה ראשית לכהן. ולא פרש בה שעור. ורבותינו נתנו בה שעור אחד מששים. וכמה צאן חיבות בראשית הגז, חמש רחלות, שנאמר (שמואל א' כה, יח) וחמש צאן עשויות. רבי עקיבא אומר ראשית גז שתים, גז צאנך ארבע, תתן לו הרי חמש:
@30 **לעמד לשרת.** מכאן שאין שרות אלא מעומד:
@32 **וכי יבא הלוי.** יכול בבן לוי ודאי הכתוב מדבר, תלמוד לומר ושרת, יצאו לויים שאין ראויין לשרות: **ובא בכל אות נפשו** וגו' **ושרת.** למד על הכהן שבא ומקריב קרבנות נדבתו או חובתו ואפלו במשמר שאינו שלו. דבר אחר עוד למד על הכהנים הבאים לרגל שמקריבין במשמר ועובדין בקרבנות הבאים מחמת הרגל, כגון מוספי הרגל, ואף על פי שאין המשמר שלהם:
@33 **חלק כחלק יאכלו.** מלמד שחולקין בעורות ובבשר שעירי חטאות. יכול אף בדברים הבאים שלא מחמת הרגל, כגון תמידין ומוספי שבת ונדרים ונדבות, תלמוד לומר לבד ממכריו על האבות, חוץ ממה שמכרו האבות בימי דוד ושמואל, שנקבעו המשמרות ומכרו זה לזה טול אתה שבתך ואני אטול שבתי:
@34 **לא תלמד לעשות.** אבל אתה למד להבין ולהורות, כלומר להבין מעשיהם כמה הם מקלקלים, ולהורות לבניך לא תעשה כך וכך, שזה הוא חק הגוים:
@35 **מעביר בנו ובתו באש.** היא עבודת המולך. עושה מדורות אש מכאן ומכאן ומעבירו בין שתיהם: **קסם קסמים.** איזהו קוסם, האוחז את מקלו ואומר אם אלך אם לא אלך. וכן הוא אומר, (הושע ד, יב) עמי בעצו ישאל ומקלו יגיד לו: **מעונן.** רבי עקיבא אומר אלו נותני עונות, שאומרים עונה פלונית יפה להתחיל. וחכמים אומרים אלו אוחזי העינים: **מנחש.** פתו נפלה מפיו, צבי הפסיקו בדרך, מקלו נפל מידו:
@36 **וחבר חבר.** שמצרף נחשים או עקרבים או שאר חיות למקום אחד: **ושאל אוב.** זה מכשפות ששמו פיתום ומדבר משחיו ומעלה את המת בבית השחי שלו: **וידעני.** מכניס עצם חיה ששמה ידוע, לתוך פיו, ומדבר העצם על ידי מכשפות: **ודרש אל המתים.** כגון המעלה בזכרותו והנשאל בגלגלת:
@37 **כל עשה אלה.** עשה כל אלה לא נאמר אלא כל עשה אלה, אפלו אחת מהן:
@38 **תמים תהיה עם ה' אלהיך.** התהלך עמו בתמימות ותצפה לו ולא תחקור אחר העתידות, אלא כל מה שיבא עליך קבל בתמימות ואז תהיה עמו ולחלקו:
@39 **לא כן נתן לך ה' אלהיך.** לשמוע אל מעוננים ואל קוסמים שהרי השרה שכינה על הנביאים ואורים ותמים:
@40 **מקרבך מאחיך כמני.** כמו שאני מקרבך מאחיך יקים לך תחתי, וכן מנביא לנביא:
@45 **אשר לא צויתיו לדבר.** אבל צויתיו לחברו: **ואשר ידבר בשם אלהים אחרים.** אפלו כון את ההלכה, לאסור את האסור ולהתיר את המתר: **ומת.** בחנק. שלשה מיתתן בידי אדם, המתנבא מה שלא שמע ומה שלא נאמר לו ונאמר לחברו, והמתנבא בשם עבודה זרה. אבל הכובש את נבואתו והעובר על דברי נביא והעובר על דברי עצמו מיתתן בידי שמים, שנאמר אנכי אדרש מעמו (פסוק יט) :
@46 **וכי תאמר בלבבך.** עתידין אתם לומר, כשיבא חנניה בן עזור ומתנבא (ירמיה כז, טז) הנה כלי בית ה' מושבים מבבלה עתה מהרה, וירמיהו עומד וצווח על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה, (שם כז, כב) בבלה יובאו עם גלות צדקיהו:
@47 **אשר ידבר הנביא.** ויאמר דבר זה עתיד לבא עליכם, ותראו שלא יבא, הוא הדבר אשר לא דברו ה' והרג אותו. ואם תאמר זו במתנבא על העתידות, הרי שבא ואמר עשו כך וכך ומפי הקדוש ברוך הוא אני אומר, כבר נצטוו שאם בא להדיחך מאחת מכל המצות לא תשמע לו, אלא אם כן ממחה הוא לך שהוא צדיק גמור, כגון אליהו בהר הכרמל שהקריב בבמה בשעת אסור הבמות כדי לגדור את ישראל. הכל לפי צורך השעה וסיג הפרצה, לכך נאמר אליו תשמעון: **לא תגור ממנו.** לא תמנע עצמך מללמד עליו חובה ולא תירא לענש עליו:
@50 **תכין לך הדרך.** מקלט מקלט היה כתוב על פרשת דרכים: **ושלשת את גבול ארצך.** שיהא מתחלת הגבול עד העיר הראשונה של עיר מקלט, כשעור מהלך שיש ממנה עד השניה. וכן משניה, לשלישית. וכן מן השלישית, עד הגבול השני של ארץ ישראל:
@52 **ונדחה ידו.** כשבא להפיל הגרזן על העץ, ותרגומו ותתמריג ידיה, לשון ונשמטה ידו להפיל מכת הגרזן על העץ. כי שמטו הבקר, תרגם יונתן (שמואל ב' ו, ו) ארי מרגוהי תוריא: **ונשל הברזל מן העץ.** יש מרבותינו אומרים נשמט הברזל מקתו, ויש מהם אומרים שישיל הברזל חתיכה מן העץ המתבקע, והיא נתזה והרגה:
@53 **פן ירדף גאל הדם.** לכך אני אומר להכין לך דרך, וערי מקלט רבים:
@55 **ואם ירחיב.** כאשר נשבע לתת לך ארץ קיני וקנזי וקדמוני:
@56 **ויספת לך עוד שלש.** הרי תשע. שלש שבעבר הירדן ושלש שבארץ כנען ושלש לעתיד לבא:
@58 **וכי יהיה איש שנא לרעהו.** על ידי שנאתו הוא בא לידי וארב לו. מכאן אמרו עבר אדם על מצוה קלה סופו לעבור על מצוה חמורה. לפי שעבר על לא תשנא, סופו לבא לידי שפיכת דמים. לכך נאמר כי יהיה איש שנא לרעהו וגו' , שהיה לו לכתוב וכי יקום איש וארב לרעהו והכהו נפש:
@60 **לא תחוס עינך.** שלא תאמר הראשון כבר נהרג, למה אנו הורגים את זה ונמצאו שני ישראלים הרוגים:
@61 **לא תסיג גבול.** לשון (ישעיה מב, יז) נסגו אחור, שמחזיר סימן חלקת הקרקע לאחור לתוך שדה חברו למען הרחיב את שלו. והלא כבר נאמר (ויקרא יט, יג) לא תגזל, מה תלמוד לומר לא תסיג, למד על העוקר תחום חברו שעובר בשני לאוין. יכול אף בחוצה לארץ, תלמוד לומר בנחלתך אשר תנחל וגו' , בארץ ישראל עובר בשני לאוין, בחוצה לארץ אינו עובר אלא משום לא תגזל:
@62 **עד אחד.** זה בנה אב. כל עד שבתורה שנים, אלא אם כן פרט לך בו אחד: **לכל עון ולכל חטאת.** להיות חברו נענש על עדותו, לא עונש גוף ולא עונש ממון, אבל קם הוא לשבועה. אמר לחברו תן לי מנה שהלויתיך, אמר לו אין לך בידי כלום, ועד אחד מעיד שיש לו, חיב להשבע לו: **על פי שני עדים.** ולא שיכתבו עדותם באגרת וישלחו לבית דין, ולא שיעמוד תרגמן בין העדים ובין הדינים:
@63 **לענות בו סרה.** דבר שאינו, שהוסר העד הזה מכל העדות הזאת, כגון, שאמרו להם והלא עמנו הייתם אותו היום במקום פלוני:
@64 **ועמדו שני האנשים.** בעדים הכתוב מדבר, ולמד שאין עדות בנשים, ולמד שצריכין להעיד עדותן מעומד: **אשר להם הריב.** אלו בעלי הדין: **לפני ה'.** יהי דומה להם כאלו עומדין לפני המקום, שנאמר (תהלים פב, א) בקרב אלהים ישפט: **אשר יהיו בימים ההם.** יפתח בדורו כשמואל בדורו, צריך אתה לנהוג בו כבוד:
@65 **ודרשו השופטים היטב.** על פי המזימין אותם, שבודקים וחוקרים את הבאים להזימם בדרישה ובחקירה: **והנה עד שקר.** כל מקום שנאמר עד, בשנים הכתוב מדבר:
@66 **כאשר זמם.** ולא כאשר עשה. מכאן אמרו, הרגו אין נהרגין: **לעשות לאחיו.** מה תלמוד לומר לאחיו, למד על זוממי בת כהן נשואה שאינן בשריפה, אלא כמיתת הבועל שהוא בחנק, שנאמר (ויקרא כא, ט) היא באש תשרף, היא ולא בועלה. לכך נאמר כאן לאחיו, כאשר זמם לעשות לאחיו, ולא כאשר זמם לעשות לאחותו. אבל בכל שאר מיתות השוה הכתוב אשה לאיש, וזוממי אשה נהרגין כזוממי איש. כגון שהעידוה שהרגה את הנפש, שחללה את השבת, נהרגין במיתתה. שלא מעט כאן אחותו אלא במקום שיש לקים בהן הזמה במיתת הבועל:
@67 **ישמעו ויראו.** מכאן שצריכין הכרזה, איש פלוני ופלוני נהרגין על שהוזמו בבית דין:
@68 **עין בעין.** ממון, וכן שן בשן וגו' :
@69 **כי תצא למלחמה.** סמך הכתוב יציאת מלחמה לכאן, לומר לך, שאין מחסר אבר יוצא למלחמה. דבר אחר לומר לך, אם עשית משפט צדק אתה מבטח שאם תצא למלחמה אתה נוצח. וכן דוד הוא אומר (תהלים קיט, קכא) עשיתי משפט וצדק בל תניחני לעשקי: **על איבך.** יהיו בעיניך כאויבים, אל תרחם עליהם כי לא ירחמו עליך: **סוס ורכב.** בעיני כלם כסוס אחד, וכן הוא אומר (שופטים ו, טז) והכית את מדין כאיש אחד. וכן הוא אומר (שמות טו, יט) כי בא סוס פרעה: **עם רב ממך.** בעיניך הוא רב, אבל בעיני אינו רב:
@70 **כקרבכם אל המלחמה.** סמוך לצאתכם מן הספר מגבול ארצכם: **ונגש הכהן.** המשוח לכך. והוא הנקרא משוח מלחמה: **ודבר אל העם.** בלשון הקדש:
@71 **שמע ישראל.** אפלו אין בכם זכות אלא קרית שמע בלבד, כדאי אתם שיושיע אתכם: **על איביכם.** אין אלו אחיכם, שאם תפלו בידם אינם מרחמים עליכם, אין זו כמלחמת יהודה עם ישראל, שנאמר (דה''י ב' כח, טו) ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה, וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל, ויביאום ירחו עיר התמרים אצל אחיהם, וישובו שמרון, אלא על אויביכם אתם הולכים, לפיכך התחזקו למלחמה: **אל ירך לבבכם אל תיראו ואל תחפזו ואל תערצו.** ארבע אזהרות כנגד ארבעה דברים שמלכי האמות עושים. מגיפים בתריסיהם כדי להקישן זה לזה כדי להשמיע קול שיחפזו אלו שכנגדם וינוסו, ורומסים בסוסיהם ומצהילין אותם להשמיע קול שעטת פרסות סוסיהם, וצווחין בקולם ותוקעין בשופרות ומיני משמיעי קול: **אל ירך לבבכם.** מצהלת סוסים: **אל תיראו.** מהגפת התריסין: **ואל תחפזו.** מקול הקרנות: **ואל תערצו.** מקול הצוחה:
@72 **כי ה' אלהיכם** וגו' **.** הם באים בנצחונו של בשר ודם ואתם באים בנצחונו של מקום. פלשתים באו בנצחונו של גלית, מה היה סופו, נפל ונפלו עמו: **ההלך עמכם.** זה מחנה הארון:
@73 **ולא חנכו.** לא דר בו. חנוך לשון התחלה: **ואיש אחר יחנכנו.** ודבר של עגמת נפש הוא זה:
@74 **ולא חללו.** לא פדאו בשנה הרביעית, שהפירות טעונין לאכלן בירושלים או לחללן בדמים ולאכל הדמים בירושלים:
@75 **פן ימות במלחמה.** ישוב פן ימות, שאם לא ישמע לדברי הכהן כדאי הוא שימות:
@76 **ויספו השטרים.** למה נאמר כאן ויספו, מוסיפין זה על דברי הכהן, שהכהן מדבר ומשמיע מן (פסוק ג, ד) שמע ישראל עד להושיע אתכם, ומי האיש ושני ושלישי כהן מדבר ושוטר משמיע, וזה שוטר מדבר ושוטר משמיע: **הירא ורך הלבב.** רבי עקיבא אומר כמשמעו, שאינו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה. רבי יוסי הגלילי אומר הירא מעבירות שבידו, ולכך תלתה לו תורה לחזור על בית וכרם ואשה לכסות על החוזרים בשביל עברות שבידם, שלא יבינו שהם בעלי עברה, והרואהו חוזר אומר שמא בנה בית או נטע כרם או ארש אשה:
@77 **שרי צבאות.** שמעמידין זקפין, מלפניהם ומלאחריהם וכשילין של ברזל בידיהם וכל מי שרוצה לחזור הרשות בידו לקפח את שוקיו. זקפין, בני אדם עומדים בקצה המערכה לזקוף את הנופלים ולחזקם בדברים שובו אל המלחמה ולא תנוסו, שתחלת נפילה ניסה:
@78 **כי תקרב אל עיר.** במלחמת הרשות הכתוב מדבר, כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחקת וגו' :
@79 **כל העם הנמצא בה.** אפלו אתה מוצא בה משבעה אמות שנצטוית להחרימם, אתה רשאי לקימם: **למס ועבדוך.** עד שיקבלו עליהם מסים ושעבוד:
@80 **ואם לא תשלים עמך ועשתה עמך מלחמה.** הכתוב מבשרך שאם לא תשלים עמך סופה להלחם בך אם תניחנה ותלך: **וצרת עליה.** אף להרעיבה ולהצמיאה ולהמיתה מיתת תחלואים:
@81 **ונתנה ה' אלהיך בידך.** אם עשית כל האמור בענין, סוף שה' נותנה בידך:
@82 **והטף.** אף טף של זכרים. ומה אני מקים (פסוק יג) והכית את כל זכורה, בגדולים:
@85 **כאשר צוך.** לרבות את הגרגשי:
@86 **למען אשר לא ילמדו.** הא אם עשו תשובה ומתגירים, אתה רשאי לקבלם:
@87 **ימים.** שנים: **רבים.** שלשה. מכאן אמרו אין צרין על עירות של נכרים פחות משלשה ימים קודם לשבת. ולמד שפותח בשלום שנים או שלשה ימים. וכן הוא אומר (שמואל ב' א, א) וישב דוד בצקלג ימים שנים, ובמלחמת הרשות הכתוב מדבר: **כי האדם עץ השדה.** הרי כי משמש בלשון דלמא. שמא האדם עץ השדה להכנס בתוך המצור מפניך להתיסר ביסורי רעב וצמא כאנשי העיר, למה תשחיתנו:
@88 **עד רדתה.** לשון רדוי, שתהא כפופה לך:
@90 **ויצאו זקניך.** מיחדים שבזקניך, אלו סנהדרי גדולה: **ומדדו.** ממקום שהחלל שוכב: **אל הערים אשר סביבת החלל.** לכל צד לידע איזו קרובה:
@92 **אל נחל איתן.** קשה, שלא נעבד: **וערפו.** קוצץ ערפה בקופיץ. אמר הקדוש ברוך הוא תבא עגלה בת שנתה שלא עשתה פרות ותערף במקום שאינו עושה פרות, לכפר על הריגתו של זה שלא הניחוהו לעשות פרות:
@95 **ידינו לא שפכה.** וכי עלתה על לב שזקני בית דין שופכי דמים הם, אלא לא ראינוהו ופטרנוהו בלא מזונות ובלא לויה. והכהנים אומרים כפר לעמך ישראל:
@96 **ונכפר להם הדם.** הכתוב מבשרם שמשעשו כן, יכפר להם העון:
@97 **ואתה תבער.** מגיד שאם נמצא ההורג אחר שנתערפה העגלה הרי זה יהרג, והוא הישר בעיני ה':

@1 **וטעם לשבטיך** . מוסב על תתן לך מלמד שמושיבים ב"ד בכל שבט ושבט ובכל עיר ועיר לשון רש"י וכן במסכת סנהדרין (טז) ולא ידעתי פירוש דבר זה כי כיון שמנינו ב"ד בכל עיר ועיר הרי בתי דינין רבים בכל שבט ושבט אולי בא לומר שאם היתה עיר אחת לשני שבטים כירושלים שיש בה חלק ליהודה ובנימין שיושיב בה שני בתי דינים וכך העלו בפרק חלק (שם קיא) שחולקים עיר אחת לשני שבטים וכן ירושלים היתה ליהודה ובנימין ויתכן לפרש שחייב הכתוב למנות ב"ד על כל השבט והוא ישפוט את כולם ואחרי כן נמנה ב"ד בכל עיר ועיר שישפוט את העיר ואע"פ שכולם שוים במנין שהם כ"ג בדיני נפשות וג' בדיני ממונות אבל הגדולים שבהם בחכמה יתמנו על כל השבט ותחתיהם לכל עיר ועיר ואין בעלי הדין יכולין לכוף זה את זה לדון אלא בפני ב"ד שבעירם לא בפני ב"ד שבעיר אחרת ואפילו היו שני בעלי הדין בעיר אחרת יכול לומר נלך לפני ב"ד שבעירנו אבל ב"ד השבט יכול לכוף כל אנשי שבטו לדון לפניו ואפילו היו הנדונים בעירם יכול לומר לב"ד הגדול של שבט אזילנא וכן אם נסתפקו בתי דינין של עיירות יבאו לפני ב"ד הגדול של שבט וישאלו כדרך שסנהדרי גדולה ממונה על כל בתי דינין של כל ישראל כך יהא ב"ד אחד ממונה על כל שבט ושבט ואם הוצרכו לתקן ולגזור דבר על שבט שלהם גוזרין ומתקנין והיא לשבט כגזרת סנהדרי גדולה על כל ישראל וזה הב"ד הוא המוזכר במסכת הוריות (ה) ששנינו בו הורו בית דין של אחד מן השבטים ועשה אותו השבט על פיהם אותו השבט חייב ושאר השבטים פטורים וכו' ועל דרך הפשט שיעור הכתוב שופטים ושוטרים תתן לך לשבטיך בכל שעריך יאמר שיתנו שופטים לשבטיהם והם ישפטו בכל שעריהם ושופט השבט ישפוט בכל שעריו
@3 **צדק צדק תרדף** . הלך אחר ב"ד יפה למען תחיה וירשת את הארץ כדאי הוא מינוי הדיינין הכשרים להחיות את ישראל ולהושיבן על אדמתם לשון רש"י מספרי (שופטים קמד) וטעם הכפל לומר הדיינין צריכין שישפטו את העם משפט צדק וגם אתה צריך לרדוף הצדק תמיד שתלך ממקומך אל מקום חכמים הגדולים אחרי רבן יוחנן בן זכאי ליבנה אחר רבי לבית שערים ור"א אמר צדק צדק פעמים שירדוף אחרי הצדק שירויח בו או יפסיד או פעם אחר פעם לחזוק אבל במדרשו של ר' נחוניא בן הקנה ידרשו בו סוד אמרו צדק זו מידת דינו של עולם שנאמר צדק צדק תרדוף וכתיב בתריה למען תחיה וירשת את הארץ אם תדין עצמך תחיה אם לאו הוא ידין עליך ותקים בעל כרחך ומאי צדק צדק תרי זימני דכתיב ( כב יג) מנגה נגדו צדק ראשון צדק ממש זו שכינה דכתיב (ישעיהו א כא) צדק ילין בה ומאי צדק שני שמפחיד את הצדיקים ומפרש שם צדק הוי כובע ישועה על ראשו ואין ראש אלא אמת שנאמר (תהלים קיט קס) ראש דברך אמת ואין אמת אלא שלום שנאמר (מלכים ב כ יט) הלא אם שלום ואמת יהיה בימי וגו' אם כן יאמר הכתוב תשפוט אתה בבית דינך ותרדוף צדק צדק ותשיג אותם למען תחיה לעולם הבא בצדק השני שהוא צדק עליון והוא האור הגדול הצפון לצדיקים לעתיד לבא והוא עוזו של הקב"ה וירשת את הארץ בצדק הראשון שהוא ארץ ישראל
@4 **לא תטע לך אשרה** . כל אילן הנטוע על פתחי בית אלהים יקרא אשרה אולי בעבור שהוא שם דרך מראה אותו לעם יקרא כן מלשון תמוך אשורי במעגלותיך (תהלים יז ה) יזהיר הכתוב שלא יטע אילן אצל מזבח ה' לנוי ויחשוב שהוא כבוד והדר למזבח השם ואסר אותו בעבור שהוא מנהג עובדי עבודה זרה לטעת אילנות בפתחי בתי עבודה זרה שלהם וכענין שנאמר (שופטים ו כה) והרסת את מזבח הבעל וגו' ואת האשרה אשר עליה תכרת ורש"י כתב לא תטע לך אשרה לחייבו עליה משעת נטיעתה ואפילו לא עבדה עובר בלא תעשה על נטיעתה ולא תטע כל עץ אצל מזבח ה' אלהיך אזהרה לנוטע ולבונה בהר הבית ואם כן יאמר לא תטע לך אשרה וכל עץ אצל מזבח ה' אבל הבונה בהר הבית אסמכתא מדבריהם כי הכתוב לא אסר אלא הנטיעה לא תטע לך אשרה ולא תטע לך כל עץ אצל מזבח ה' אלהיך
@5 **ולא תקים לך מצבה** . מצבת אבן אחת להקריב עליה אפילו לשמים אשר שנא מזבח אדמה ומזבח אבנים צוה לעשות ואת זו שנא כי חוק היתה לכנענים ואע"פ שהיתה אהובה לו בימי האבות עכשיו שנאה מאחר שעשאוה אלו חוק לע"ז לשון רש"י ואם כן אסר הכתוב האשרה ואסר כל נוטע בהר הבית אע"פ שכוונתו לשמים ואסר המצבה לשמים ושניהם מפני חוקת הכנעניים אבל לא הבינותי החק הזה שהרי הכנעניים גם במזבחות גם במצבות היו נוהגים שהכתוב אומר ונתצתם את מזבחותם ושברתם את מצבותם (לעיל יב ג) כי את מזבחותם תתצון ואת מצבותם תשברון (שמות לד יג) וכן בכל מקום ואולי נאמר שהחזיקו הכנענים במצבות ולא היה להם בית ע"ז שאין שם מצבה להקטיר עליה ולצוק שמן על ראשה וכענין שנאמר בבעל (מלכים ב י כו) ויוציאו את מצבות בית הבעל אבל המזבחות היו במקצתן להקריב גם בהם והנראה בעיני כי היו הכנענים השטופים בע"ז עושים בכל בתי אלהיהם מזבח להקריב עליו הקרבנות ואבן גדולה מוצבת על פתח הבית לעמוד עליה הכומרים ואילן נטוע חוצה לה לאשר דרך הבאים שם וגם היום הנוצרים עושים כן והנה השם הנכבד שנא ומאס כל מעשיהם ואסר המצבה והאשרה ולא השאיר רק המזבח שהוא צורך הקרבנות אשר הוא יתברך צוה בהם והיו נחת רוח לפניו שאמר ונעשה רצונו מאז קודם היות ע"ז בעולם וטעם אשר שנא ביאור כי השם צוה (שמות כ כד כה) מזבח אדמה תעשה לי ואם מזבח אבנים תעשה לי וביאר משה כי באלה יחפוץ להוציא המצבה כי שנאה כי כל מעשיהם שנואין לפניו וצוה את ישראל שלא יעשו כמעשיהם אבל בימי יעקב לא נאמר עדיין ובחקותיהם לא תלכו (ויקרא יח ג) ולכך היה משתמש במצבה לשם שמים כמנהג העובדים והנה זו מצוה מבוארת מן ואם מזבח אבנים תעשה לי אבל מה שאמר בתורה (שם כו א) ופסל ומצבה לא תקימו לכם הם פסל ומצבה להושיב הפסל על המצבה לע"ז כי שם בענין ע"ז דיבר הכתוב אבל יאמר (שם) ואבן משכית לא תתנו בארצכם להשתחוות עליה אפילו לשמים מפני שהוא נראה כעובד לשכיות ההם כטעם האשרה שהיא מחוקות העמים ודע כי מזבח הוא בנין אבנים גבוה ולו קרנות ארבע ולו יסוד סובב יעלו על יסודו ומקריבים בין קרנותיו והמצבה אבן אחת גדולה ירימוה להקטיר או להקריב עליה או להיות הכומרים עומדים עליה והבמה כענין הר ועושים אותה מעפר מקובץ ועליה מזבח בנוי להקריב בו כי כל דבר רם וגבוה יקראו כן אעלה על במתי עב (ישעיהו יד יד) על במותי ארץ (דברים לב יג) גם גב האדם יקרא במה על במותימו תדרך (שם לג כט) וכן אמר הכתוב (מלכים א ג ד) וילך המלך גבעונה לזבוח שם כי היא הבמה הגדולה אלף עולות יעלה שלמה על המזבח ההוא
@6 **לא תזבח לה' אלהיך כל דבר רע** . אזהרה למפגל קדשים על ידי דבור רע ועוד נדרשו בו שאר דרשות בשחיטת קדשים לשון רש"י והנה זו מצוה מבוארת שכבר הזהיר על השוחט בעלי מומים (ויקרא כב כב) וחזר להוסיף המפגל והקרוב כי החזיר האזהרה הזאת בעבור הישראלי המקריב שלא יפגל בשחיטה אבל הכהנים זריזים ומוזהרים הם ודיים בהתראה אחת ולכך לא החזיר מום המקריבים וטעם כי תועבת ה' אלהיך הוא הזבח הזה כי הזובח משחת לה' בוזה הוא כאמור בקבלה (מלאכי א יד) וארור נוכל וגו' ונודר וזובח משחת לה' כי מלך גדול אני ועל פי המדרש (ספרי קמז) תהיה התועבה ברובע ונרבע באתנן ומחיר שהם תועבות
@7 **כי ימצא בקרבך באחד שעריך אשר ה' אלהיך נתן לך** . כבר פירשתי (לעיל יא לב) כי כאשר ידבר במשפטים יזכיר תחילה המשפט בע"ז או בעובדיה ואמר באחד שעריך אשר ה' אלהיך וגו' ולא שיהיה זה בארץ ישראל בלבד שאף העובד בחוצה לארץ בסקילה אבל ענין הכתוב שאמר כי ימצא הדבר באחת מן הערים הרחוקות שיתן לך השם כאשר ירחיב את גבולך והוגד לך ושמעת באיזה עיר שתהיה אתה שם תדרוש הדבר היטב וכאשר תדע שהוא אמת והוצאת אותם אל השער ההוא שעבד בו וסקלתם ואמר (בפסוק ד) נעשתה התועבה הזאת בישראל לחייב אפילו בחוצה לארץ כי בעיר הנדחת אמר (לעיל יג טו) נעשתה התועבה הזאת בקרבך אבל כאן הזכיר "באחד שעריך" שדיבר בהווה כאשר פירשנו ואחר כך הזכיר "בישראל" ללמד שנוהג זה בכל ישראל ועוד הוצרך לומר "באחד שעריך" ללמד שיסקל על שער שעבד בו וזה בארץ כי בחוצה לארץ נסקל על פתח בית דין שנדון בו והמצוה הזו מבוארת שכבר אמר (שמות כב יט) זובח לאלהים יחרם והוא בכל מקום ובכל זמן ולכך ישנה אותה לבאר מה שיצטרך להוסיף במצוה ויקצר בדבר הנזכר ועל דרך האמת יתכן כי הזכיר "באחד שעריך" בעבור שאמר "לעבור בריתו" והיא התועבה הנעשית בישראל יודיע הכתוב הברית בארץ הברית אבל הדר בחוצה לארץ כאילו עובד ע"ז וכבר הזכרתי הענין הזה (ויקרא יח כה) והזכיר איש או אשה כי בעבור קלות דעת האשה תתפתה לעבוד ע"ז באות או מופת שנעשה לפניה והעד נשי ירמיהו (ירמיהו מד) וכן הזכיר באוב וידעוני (ויקרא כ כז) "או אשה" לרגילות הנשים בהם כמו שאמר (שמות כב יז) מכשפה לא תחיה ובספרי (שופטים קמח) דרשו כי בעבור שאמר במדיח (לעיל יג יד) יצאו אנשים בני בליעל ואין הדין ההוא ככה בנשים הוצרך לפרש בעובד שהוא שוה באיש ובאשה וטעם אשר לא צויתי מפורש "()" "סגירה"
@8 **כי ימצא בקרבך באחד שעריך אשר ה' אלהיך נתן לך** . כבר פירשתי (לעיל יא לב) כי כאשר ידבר במשפטים יזכיר תחילה המשפט בע"ז או בעובדיה ואמר באחד שעריך אשר ה' אלהיך וגו' ולא שיהיה זה בארץ ישראל בלבד שאף העובד בחוצה לארץ בסקילה אבל ענין הכתוב שאמר כי ימצא הדבר באחת מן הערים הרחוקות שיתן לך השם כאשר ירחיב את גבולך והוגד לך ושמעת באיזה עיר שתהיה אתה שם תדרוש הדבר היטב וכאשר תדע שהוא אמת והוצאת אותם אל השער ההוא שעבד בו וסקלתם ואמר (בפסוק ד) נעשתה התועבה הזאת בישראל לחייב אפילו בחוצה לארץ כי בעיר הנדחת אמר (לעיל יג טו) נעשתה התועבה הזאת בקרבך אבל כאן הזכיר "באחד שעריך" שדיבר בהווה כאשר פירשנו ואחר כך הזכיר "בישראל" ללמד שנוהג זה בכל ישראל ועוד הוצרך לומר "באחד שעריך" ללמד שיסקל על שער שעבד בו וזה בארץ כי בחוצה לארץ נסקל על פתח בית דין שנדון בו והמצוה הזו מבוארת שכבר אמר (שמות כב יט) זובח לאלהים יחרם והוא בכל מקום ובכל זמן ולכך ישנה אותה לבאר מה שיצטרך להוסיף במצוה ויקצר בדבר הנזכר ועל דרך האמת יתכן כי הזכיר "באחד שעריך" בעבור שאמר "לעבור בריתו" והיא התועבה הנעשית בישראל יודיע הכתוב הברית בארץ הברית אבל הדר בחוצה לארץ כאילו עובד ע"ז וכבר הזכרתי הענין הזה (ויקרא יח כה) והזכיר איש או אשה כי בעבור קלות דעת האשה תתפתה לעבוד ע"ז באות או מופת שנעשה לפניה והעד נשי ירמיהו (ירמיהו מד) וכן הזכיר באוב וידעוני (ויקרא כ כז) "או אשה" לרגילות הנשים בהם כמו שאמר (שמות כב יז) מכשפה לא תחיה ובספרי (שופטים קמח) דרשו כי בעבור שאמר במדיח (לעיל יג יד) יצאו אנשים בני בליעל ואין הדין ההוא ככה בנשים הוצרך לפרש בעובד שהוא שוה באיש ובאשה וטעם אשר לא צויתי מפורש
@11 **על פי שנים עדים או שלשה עדים** . "אם מתקיימת עדות בשנים, למה פרט לך בשלשה? - להקיש שלשה לשנים: מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כולן"; לשון רש"י.
@11 וכן, אם נמצא אחד מהם קרוב או פסול, העדות כולה בטלה, והם כולם נהרגים ומשלמים ממון בהזמתן, שעיקר הכתוב להקיש שלשה לשנים בכל דבריהם, כדעת רבותינו (מכות ה ב).
@11 ועל דרך הפשט, אמר הגאון רב סעדיה: שנים - עדים, או שלשה - מקבלי עדות השנים. ואין בכתוב קבלת עדות, רק עדים. אבל כמדומה לי שטעה הגאון בדינו, כי עדות דיני נפשות לא תקובל רק בפני סנהדרין של עשרים ושלשה.
@11 אבל פשוטו של מקרא לאמר, שיומת המת על פי שנים עדים כשאין שם יותר, או על פי שלשה אם ימצאון שם שלשה; יאמר הכתוב, כאשר הוגד לך ושמעת, תדרוש הדבר היטב על פי כל העדים הנמצאים שם. והנה, אם שמענו שעבר בפני שלשה, נשלח בעבורם ויבואו לבית דין ויעידו כולם, והוא הדין למאה; כי בשמענו דברי כולם יתברר האמת. ואם לא היו שם יותר, או שהלכו להם ואינם נמצאים שם, בשנים די.
@13 **דברי ריבת** . שיהיו חכמי העיר חלוקים בדבר זה מטמא וזה מטהר זה מחייב וזה מזכה לשון רש"י והיא דעת אונקלוס ואיננו נכון אבל כפי מדרשו (ספרי שופטים קנב) בין דם לדם בין דם נדה לדם יולדת ולדם זבה בין דין לדין בין דיני ממונות לדיני נפשות לדיני מכות ובין נגע לנגע בין נגעי אדם לנגעי בתים לנגעי בגדים דברי ריבות השקאת הסוטה ועריפת העגלה וטהרת המצורע והנה טעמו ובין והלמ"ד לדעתם תשמש כמו בי"ת בין דם בדם דין בדין כלומר שיפלא דבר למשפט באחד מכל הדמים ובאחד מכל הדינין וכמוהו לוז שם העיר לראשונה (בראשית כח יט) בראשונה נגפו ה' במעיו לחלי לאין מרפא (דהי"ב כא יח) בחולי באין מרפא ויחפהו זהב טוב לככרים שש מאות (שם ג ח) בככרים וכן רבים או טעמו בין דם לכל הדמים בין דין לכל הדינין וכן וכל ריב אשר יבוא עליכם מאחיכם וגו' בין דם לדם בין תורה למצוה לחוקים ולמשפטים והזהרתם אותם ולא יאשמו לה' (שם יט י) וכפי פשוטו בין דם לדם וגו' בין ענין רציחות או דיני ממון או פצע וחבורה כל דברי ריבות אשר יהיו בשעריך ודיבר הכתוב בהווה כי בענייני המשפטים יהיו המחלוקות יותר משאר ההוראות אבל דין הזקן שוה בכולם ולכך אמר (פסוק יא) ועשית על פי התורה וגו' ועל המשפט וגו' כי "התורה" תרמוז לשאר ההו ראות
@16 **ימין ושמאל** . אפילו אם אומר לך על ימין שהוא שמאל או על שמאל שהוא ימין לשון רש"י וענינו אפילו תחשוב בלבך שהם טועים והדבר פשוט בעיניך כאשר אתה יודע בין ימינך לשמאלך תעשה כמצותם ואל תאמר איך אוכל החלב הגמור הזה או אהרוג האיש הנקי הזה אבל תאמר כך צוה אותי האדון המצוה על המצות שאעשה בכל מצותיו ככל אשר יורוני העומדים לפניו במקום אשר יבחר ועל משמעות דעתם נתן לי התורה אפילו יטעו וזה כענין רבי יהושע עם ר"ג ביום הכיפורים שחל להיות בחשבונו (ר"ה כה) והצורך במצוה הזאת גדול מאד כי התורה נתנה לנו בכתב וידוע הוא שלא ישתוו הדעות בכל הדברים הנולדים והנה ירבו המחלוקות ותעשה התורה כמה תורות וחתך לנו הכתוב הדין שנשמע לבית דין הגדול העומד לפני השם במקום אשר יבחר בכל מה שיאמרו לנו בפירוש התורה בין שקבלו פירושו עד מפי עד ומשה מפי הגבורה או שיאמרו כן לפי משמעות המקרא או כוונתה כי על הדעת שלהם הוא נותן (ס"א לנו) להם התורה אפילו יהיה בעיניך כמחליף הימין בשמאל וכל שכן שיש לך לחשוב שהם אומרים על ימין שהוא ימין כי רוח השם על משרתי מקדשו ולא יעזוב את חסידיו לעולם נשמרו מן הטעות ומן המכשול ולשון ספרי (שופטים קנד) אפילו מראין בעיניך על הימין שהוא שמאל ועל שמאל שהוא ימין שמע להם
@19 **ואמרת אשימה עלי מלך** . על דעת רבותינו (ספרי ראה סז, סנהדרין כ א) כמו "ואמור אשימה עלי מלך", והיא מצות עשה, שיחייב אותנו לומר כן אחר ירושה וישיבה, כלשון (דברים כב ח): "ועשית מעקה לגגך" וזולתם. והזכיר "ואמרת", כי מצוה שיבואו לפני הכהנים הלוים ואל השופט, ויאמרו להם 'רצוננו שנשים עלינו מלך'.
@19 ולפי דעתי עוד, שגם זה מרמיזותיו על העתידות, שכן היה כששאלו להם את שאול, אמרו לשמואל (שמואל א ח ה): "שימה לנו מלך לשפטנו ככל הגוים", וכן כתוב שם (שמואל א ח כ): "והיינו גם אנחנו ככל הגוים ושפטנו מלכנו וגו'", כי מה טעם שתאמר התורה במצוה "ככל הגוים אשר סביבותי", ואין ישראל ראויים ללמד מהם ולא לקנא בעושי עולה! אבל זה רמז לענין שיהיה, ולכך באה הפרשה בלשון הבינוני, כאשר פירשתי כבר.
@20 **וטעם אשר יבחר ה' אלהיך בו** .
@20 על דעת המפרשים, שיהיה נבחר על פי נביא או במשפט האורים, יצוה הכתוב תשים עליך מלך אשר יבחר ה' אלהיך בו, כי הוא יבחר ולא אתה. ובספרי: "שום תשים עליך מלך - מת מנה אחר תחתיו, מלך - ולא מלכה, אשר יבחר ה' אלהיך - על פי נביא".
@20 אם כן, מה טעם להזהיר "לא תוכל לתת עליך איש נכרי", והשם לא יבחר בנכרי?
@20 אבל לדעת רבותינו יש בכתוב הזה תנאי נסתר, יאמר שום תשים עליך המלך שיבחר השם בו אם תוכל לעשות כן שיענך השם בנביאים, אבל איש נכרי לא תוכל לתת עליך לעולם.
@20 ועל דרך הפשט אמרו: שום תשים עליך מלך אשר יבחר ה' אלהיך בו, ולא אשר שנא ה' אלהיך, כי הוא בחר בישראל ולהיות המולך מבחוריו ולא מקרב העמים אשר שנא.
@20 ודעתי בדרך הפשט, כי טעם "אשר יבחר" שכל מולך על עמים מאת האלהים היא לו, כענין שכתוב (דניאל ד כט): "די שליט עלאה במלכות אנשא ולמאן די יצבא יתננה". וכך אמרו (ב"ב צא) אפילו ריש גרגותא מן שמיא מוקמי ליה. יאמר "שום תשים עליך מלך, כל אשר יהיה נגזר מן השמים שימלוך, ואם הוא מקטני שבטי ישראל ומשפחתו הצעירה; אבל איש נכרי לא תמליך עליך לעולם". וכן על דרך הפשט "המקום אשר יבחר ה' אלהיך בו", כל שיבנו שם בית המקדש לה', הכל מרצון ה'.
@21 **לא ירבה לו סוסים** . אלא כדי מרכבתו כדי שלא ישיב את העם מצרימה שהסוסים באים משם שנאמר (מלכים א י כט) ותעלה ותצא מרכבה ממצרים בשש מאות כסף לשון רש"י והוקשה לי בזה כי אמרו בירושלמי בסוף סנהדרין (סוף פ"י) לישיבה אי אתה חוזר אבל אתה חוזר לסחורה לפרקמטיא ולכבוש הארץ ואם ישלח המלך ויקנה משם הסוסים והרכב סחורה היא זו ומותר ויתכן שדרך הכתוב כי הזהיר לא ירבה לו סוסים אפילו מארצו ומארץ שנער או בדרך סחורה המותרת שלא יבטח על רכבו כי רב ועל פרשיו כי עצמו מאוד אבל יהיה מבטחו בשם אלהיו ואחר כך הזהיר על המלך שלא ישיב את העם מצרימה שיהיו לו שם מעבדיו ומעמו שרי מקנה יושבים בערי הרכב למען הרבות סוס כענין שנאמר בשלמה (מלכים א ט יט) ואת כל ערי המסכנות אשר היו לשלמה ואת ערי הרכב וגו' וכן היו לו במצרים כמו שאמר (שם י כח) ומוצא הסוסים אשר לשלמה ממצרים ומקוה סחרי המלך וגו' שלא היה אדם רשאי להוציא ממצרים סוסים שלא ברשות מלך מצרים והיו נותנים לו מכס מהם ונתן פרעה לשלמה מוצא הסוסים לומר שיוציא הוא כרצונו והוא שיתן הרשות לאשר ירצה ויהא המכס שלו והיו לו שם הסוחרים עומדים במצרים קונים הסוסים כולם ושולחים אל אדוניהם כרצונו ומוכרים האחרים לשאר מלכי הארץ והוא שאמר (שם פסוק כט) וכן לכל מלכי החתים ולכל מלכי ארם בידם יוציאו כלומר על ידי סוחרי שלמה יוציאו אותם ולו יתנו המכס וטעם רק לומר אף על פי שתשים עליך מלך ככל הגוים אשר סביבותיך רק לא יהיה כמלכיהם שלא ירבה סוסים כאשר יעשו הם שכל חפצם במלכים למען הרבות להם סוסים ופרשים וטעם וה' אמר לכם כי השם אומר לכם שלא תוסיפון לשוב בדרך מצרים וכן כאשר צוך ה' אלהיך (לעיל ה טז) שהוא מצוה אותך כן או "אמר לכם" שאמר לי כן לצוות אתכם כדרך ויאמר משה כה אמר ה' כחצות הלילה וגו' (שמות יא ד) ועל דרך רבותינו (ירושלמי סוכה פ"ה ה"א) כי כאשר ראיתם את מצרים היום לא תוסיפו לראותם עוד עד עולם (שמות יד יג) מצוה ומשה הזכיר וה' אמר לכם שלא תוסיפון לשוב בדרך הזה עוד וכבר פירשתיו (שם) וטעם המצות הזאת מפני שהיו המצרים והכנענים רעים וחטאים לה' מאד כמו שאמר (ויקרא יח ג) כמעשה ארץ מצרים אשר ישבתם בה לא תעשו וכמעשה ארץ כנען וגו' והנה רצה ה' שלא ילמדו ישראל ממעשיהם והכרית בכנענים כל נשמה (להלן כ טז) ואמר (שמות כג לג) לא ישבו בארצך והזהיר במצרים שלא נשב אנחנו שם בארצם
@24 **והיתה עמו** . התורה הנזכרת וקרא בו בספר הנזכר ועל דרך האמת והיתה עמו התורה עצמה תהיה עמו כדרך וה' נתן חכמה לשלמה (מלכים א ה כו) ואומר וישב שלמה על כסא ה' למלך (דהי"א כט כג)
@25 **לבלתי רום לבבו מאחיו** . נרמז בכאן בתורה איסור הגאות כי הכתוב ימנע את המלך מגאות ורוממות הלב וכל שכן האחרים שאינן ראויים לכך כי בראוי להתרומם ולהתגדל יזהירנו להיות לבבו שפל ככל אחיו הקטנים ממנו כי הגאוה מדה מגונה ונמאסת אצל האלהים אפילו במלך כי לה' לבדו הגדולה והרוממות ולו לבדו התהלה ובו יתהלל האדם כענין המבואר על יד המלך שלמה (משלי טז ה) תועבת השם כל גבה לב וכתיב (ירמיהו ט כג) כי אם בזאת יתהלל המתהלל השכל וידוע אותי וגו'
@26 **אשי ה'** . קדשי המקדש נחלתו אלו קדשי הגבול תרומות ומעשרות אבל נחלה גמורה לא יהיה לו בקרב אחיו ובספרי דרשו ונחלה לא יהיו לו זו נחלת שאר בקרב אחיו זו נחלת שבעה ואיני יודע מה הוא ונראה לי שארץ כנען שמעבר הירדן ואילך נקראת ארץ חמשה עממין ושל סיחון ועוג שני עממין אמורי וכנעני ונחלת שאר לרבות קיני וקנזי וקדמוני שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי (שופטים קסד) ונחלה לא יהיה לו אלו נחלת חמשה בקרב אחיו אלו נחלת שבעה נחלת חמשה שבטים ונחלת שבעה שבטים ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד שכן משה הנחיל לראובן וגד ולחצי שבט מנשה ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה ושבעה אחרים נטלו מאיליהן אחרי מות יהושע מתוך כך הזכיר חמשה לבד ושבעה לבד כל זה לשון רש"י וכבר פירשתי העיקר בפרשת קדש לי (שמות יג ה) כי נחלת חמשה עממין הנזכרים בפסוק כי יביאך ה' אל ארץ הכנעני והחתי והאמורי והחוי והיבוסי אשר נשבע לאבותיך לתת לך ארץ זבת חלב ודבש והם עיקר נחלת ישראל שהיתה ארצם זבת חלב ודבש אבל השנים הנשארים והם הפרזי והגרגשי אין ארצם זבת חלב ודבש ואינה חייבת בבכורים ולכך הזכיר בלויים שלא יטלו חלק עם ישראל בעיקר נחלתם בארץ הטובה שהיא נחלת החמשה וגם לא בנחלת השבעה שהם השנים הנשארים אף על פי שאין ארצם טובה ואינה חשובה בעיני ישראל כל כך ודבר ברור הוא בראיות שכתבתי שם
@28 **וזה יהיה משפט הכהנים** . זו מצוה מחודשת לא נזכרה בתורה כי במדבר שלא היו זובחים שור ושה רק שלמים לא הזכירה להם שאינה נוהגת במוקדשים ועתה כשבאו ליכנס לארץ חדשה להם וזה טעם מאת זבחי הזבח כלומר כאשר יזבחו הזבח שהתרתי לכם (לעיל יב כא) וזבחת מבקרך ומצאנך כאשר צויתיך ואכלת בשעריך והנה לא נתן אותה לאהרן בפרשת ויאמר ה' אל אהרן (במדבר יח ח) אע"פ שנתן לו שם התרומות והבכורים שאינם נוהגים אלא בארץ והטעם כי שם הזכיר כל אשר נתן לו בקדש כי גם החרם קדש הוא אבל הזרוע והלחיים והקיבה וראשית הגז הן חולין גמורין אין בהם זולתי מצות המתנה וכן לא הזכיר שם גזל הגר ועל מדרש רבותינו כולם נרמזות שם ראשיתם זו ראשית הגז אשר יתנו זו הזרוע והלחיים והקיבה לה' זו חלה בספרי (קרח קיז) אם כן גם זו מצוה מבוארת ועל סמך המדרש שאמרו (חולין קלד) זרוע תחת ויקח רמח בידו (במדבר כה ז) לחיים תחת תפלה שנאמר (תהלים קו ל) ויעמוד פינחס ויפלל וגו' הקבה תחת האשה אל קבתה (במדבר כה ח) נרמזו שם על הזכות שעתיד להיות וזיכה לכל השבט בזכות פנחס כאשר זיכה לפנחס להיות כהן עמהם והרב אמר במורה הנבוכים (ג לט) כי הלחיים בעבור היותם ראשית לגוף והזרוע בעבור היותו ראשית האברים המשתרגים בגוף והקיבה ראשית המעים כי הראשית בכולם ינתנו למשרתי עליון לכבודו
@34 **לא תלמד לעשות כתועבת הגוים ההם** . גם זו מצוה מבוארת שכבר אמר (ויקרא יח ג) וכמעשה ארץ כנען אשר אני מביא אתכם שמה לא תעשו ובחקתיהם לא תלכו ועתה יזכיר מעשיהם ויאמר שהם תועבה לפני השם והזכיר מעביר בנו ובתו באש והוא מין ממיני הכשוף על דרך הפשט או המולך על דעת רבותינו (סנהדרין סד) והוא האמת כמו שפירשתי במקומו (ויקרא יח כא) והזכיר מכשף שם כלל לכל הכשפים וחובר חבר ושואל אוב וידעוני והם פרטים בכשוף ואסר אותם גם לשואל ודרש אל המתים כאוב עצמו ובכל ענין שידרוש אליהם והזכיר קוסם קסמים והיא מחשבה בעתידות בכלל מלשון קסם על שפתי מלך במשפט לא ימעל פיו (משלי טז י) כמו שאמר (יהושע יג כב) בלעם בן בעור הקוסם והיה מנחש כמו שאמר בו (במדבר כד א) ולא הלך כפעם בפעם לקראת נחשים וכתיב (שמואל א כח ח) קסמי נא לי באוב והזכיר בפרט מעונן והוא היודע בעננים ומנחש הוא המביט בעופות בכנפיהם או בצפצוף כענין שכתוב (קהלת י כ) כי עוף השמים יוליך את הקול ובעל כנפים יגיד דבר והוא לשון נגזר מלשון חשתי ולא התמהמהתי (תהלים קיט ס) שכל מה שימהר להודיע בעתיד קודם היותו יקרא נחש כלומר נחיש ונקדים לדעת ואמר הכתוב כי תועבת ה' כל עושה אלה ולא אמר "עושה כל אלה" כי הכתוב ידבר על רובם כי המעונן והמנחש אינה תועבה ולא הוריש הכנענים בעבורם כי כל בני אדם יתאוו לדעת עתידות למו ומתעסקין בחכמות רבות כאלה לדעתם ועתה דע והבן בעניני הכשפים כי הבורא יתברך כאשר ברא הכל מאין עשה העליונים מנהיגי התחתונים אשר למטה מהן ונתן כח הארץ וכל אשר עליה בכוכבים ובמזלות לפי הנהגתם ומבטם בהם כאשר הוא מנוסה בחכמת האיצטגנינות ועשה עוד על הכוכבים והמזלות מנהיגים מלאכים ושרים שהם נפש להם והנה הנהגתם מעת היותם עד לעולם ועד גזירת עליונים אשר שם להם אבל היה מנפלאותיו העצומות ששם בכח המנהיגים העליונים דרכי תמורות וכחות להמיר הנהגת אשר למטה מהם שאם יהיה מבט הכוכבים (בפניו) בפנים אשר כנגד הארץ טובה או רעה לארץ או לעם או לאיש ימירו אותם הפנים העליונים עליו להפך במבט עצמו כענין שאמרו תמורת ענג נגע ועשה כן להיות הוא יתברך שמו מהשנא עדניא וזמניא קורא למי הים לעשות בהם כרצונו והופך לבקר צלמות מבלי שינוי טבעו של עולם ושיעשו הכוכבים והמזלות מהלכם כסדרן ועל כן אמר בעל ספר הלבנה החכם בנגרמונסי"א כשהלבנה והיא נקראת גלגל העולם בראש טלה על דרך משל ויהיה פניו מול פלוני תעשה תמונה לדבר פלוני ויוחק בה שם השעה ושם המלאך הממונה עליה מן השמות ההם הנזכרים באותו הספר ותעשה הקטרה פלונית בענין כך וכך יהיה המבט עליה לרעה לנתוש ולנתוץ ולהאביד ולהרוס וכאשר תהיה הלבנה במזל פלוני תעשה תמונה והקטרה בענין פלוני לכל טובה לבנות ולנטוע והנה גם זה הנהגת הלבנה בכח מנהיגיה אבל ההנהגה הפשוטה אשר במהלכה הוא חפץ הבורא יתברך אשר שם בהם מאז וזה היפך וזה סוד הכשפים וכחם שאמרו בהם (חולין ז) שהם מכחישים פמלייא של מעלה לומר שהם היפך הכחות הפשוטים והם הכחשה לפמלייא בצד מהצדדין ועל כן ראוי שתאסור אותם התורה שיונח העולם למנהגו ולטבעו הפשוט שהוא חפץ בוראו וגם זה מטעמי איסור הכלאים כי יבואו מן ההרכבות צמחים יעשו פעולות נכריות יולידו שינויים ממנהגו של עולם לרע או לטוב מלבד שהן עצמן שינוי ביצירה כאשר פירשתי כבר (ויקרא יט יט) ורבים יתחסדו בנחשים לומר שאין בהם אמת כלל כי מי יגיד לעורב ולעגור מה יהיה ואנחנו לא נוכל להכחיש דברים יתפרסמו לעיני רואים ורבותינו גם כן יודו בהם כמו שאמרו בואלה שמות רבה (ויק"ר לב ב קהלת רבה י כג) כי עוף השמים יוליך את הקול (קהלת י כ) זה העורב וחכמת הטיארין העופות בלשון ערב טאי"ר וחכמי העופות יקראו טיארין ועוד מוזכר מזה הענין בגמרא (גיטין מה) אבל יש לענין הזה סוד וכבר הודענו (ויקרא יח כה) כי יש למזלות שרים ינהיגו אותם והם נפשות לכדורי הגלגלים ושרי זנב וטלה הקרובים לארץ והם הנקראים נגידי התלי יודיעו העתידות ומהם נעשים סימנים בעופות שבהם יודיעו עתידות ולא לזמן גדול ולא עתידות רחוקות יגידו רק בעתידות הקרובות לבא יודיעו מהם בקול העוף בקראו בקול מר על מת ומהם בפרישות כנפיו והוא שאמר יוליך את הקול למגידים בקולם ובעל כנפים לרומזים בכנפיהם וכל זה איננו תועבה בעמים אבל חכמה תחשב להם וכך אמרו (במדב"ר יט ג) ותרב חכמת שלמה מחכמת כל בני קדם (מלכים א ה י) מה היתה חכמתן של בני קדם שהיו יודעין וערומים בטייר וכן יאמר הכתוב (ישעיהו ב ו) כי מלאו מקדם ועוננים כפלשתים והנה שלמה למד זה בכלל חכמותיו והידיעה היא הבנת הצפצוף והערמה לסבור ענין בפרישות הכנפים וכאשר כלל הכתוב המעוננים והקוסמים עם התועבות הנזכרות חזר ופירש (בפסוק יד) הגוים האלה אשר אתה יורש אותם אל מעוננים ואל קוסמים ישמעו כי חכמתם לדעת הבאות ואתה לא כן נתן לך ה' אלהיך יאמר הנה אסר לך השם המעשים האלה הנזכרים בעבור שהם תועבות לפניו ובגללם הוריש הגוים ההם מפניך ואסר לך הנחשים והקסמים בעבור שעשה לך מעלה גדולה לתתך עליון על כל גויי הארץ שיקים בקרבך נביא ויתן דבריו בפיו ואתה תשמע ממנו מה יפעל אל ולא תצטרך אתה בעתידות אל קוסם ומנחש שיקבלו אותם מן הכוכבים או מן השפלים בשרי מעלה שאין כל דבריהם אמת ולא יודיעו בכל הצריך אבל הנבואה תודיע חפץ השם ולא יפול דבר מכל דבריה והוא שיפרש (בפסוק כב) הוא הדבר אשר לא דברו ה' והנה אתה חלקו וסגולתו שומע עצתו מפיו והם חלק המזלות הולכים אחריהם וזה טעם לא כן נתן לך ה' אלהיך שלא נתן לך כאשר נתן להם כטעם אשר חלק ה' אלהיך אותם לכל העמים (לעיל ד יט) כאשר פירשתי (ויקרא יח כה) ובספרי (שופטים קעד) אל מעוננים ואל קוסמים ישמעו שמא תאמר להם יש במה לשאול ולי אין לי לשאול תלמוד לומר ואתה לא כן נתן לך ה' אלהיך והנה זו ראיה בכל מה שפירשנו כי הנחשים שורש דבר נמצא בם ולכן היה לישראל טענה במניעה מהם
@38 **וטעם תמים תהיה עם ה' אלהיך** . שנייחד לבבנו אליו לבדו ונאמין שהוא לבדו עושה כל והוא היודע אמתת כל עתיד וממנו לבדו נדרוש העתידות מנביאיו או מאנשי חסידיו רצונו לומר אורים ותומים ולא נדרוש מהוברי שמים ולא מזולתם ולא נבטח שיבואו דבריהם על כל פנים אבל אם נשמע דבר מהם נאמר הכל בידי שמים כי הוא אלהי האלהים עליון על הכל היכול בכל משנה מערכות הכוכבים והמזלות כרצונו מפר אותות בדים וקוסמים יהולל ונאמין שכל הבאות תהיינה כפי התקרב האדם לעבודתו ולפיכך אחר אזהרת שאלת העתידות מקוסם ודורש בעד החיים אל המתים אמר שתהיה תמים עם השם בכל אלה ולא תירא ממגיד עתיד אבל מנביאו תדרוש ואליו תשמע וזה דעת אונקלוס שלים תהא בדחלתא דה' אלהך שלא תהיה חסר ביראתו כי "תמים" הוא השלם בדבר כמו שה תמים (שמות יב ה) שאין בו מום ושום חסרון וזו מצות עשה וכבר הזכרתי זה בפסוק והיה תמים (בראשית יז א)
@40 **נביא מקרבך מאחיך כמני** . טעם "מקרבך" לרמוז שאין נבואה אלא בארץ ישראל ולכך יאמר בה הכתוב (ישעיהו כב א) משא גיא חזיון וכמו שהזכירו רבותינו (מכילתא ריש בא) וכן טעם "מאחיך" כי השם נתן לך מעלה על כל העמים ולא יתן רוחו רק עליכם כמוני שאני מקרב אחיך יקים לך תחתי וכן מנביא לנביא לשון רש"י ואמר רבי אברהם כמוני שאני נביא השם לא מעונן וקוסם ויתכן שיהיה "מקרבך" לומר שתוכל לבטוח בדבריו שהוא מאחיך מקרבך וכן על דעתי "כמוני" שיהיה נאמן לנביא לה' ותאמין בו כאשר אתה מאמין בי ועוד אבאר זה
@41 **ככל אשר שאלת וגו'** . לא השלים הכתוב בכאן השאלה ששאלו כי באמרם לא אוסיף לשמוע את קול ה' לא יזכו לנביאים אבל כאשר אמרו (לעיל ה כד) קרב אתה ושמע את כל אשר יאמר ה' אלהינו ואת תדבר אלינו את כל אשר ידבר ה' אלהינו אליך ושמענו ועשינו אז קבלו להאמין בנביאיו ולשמוע ולעשות ככל אשר יצוה השם על ידם ולכך אמר בכאן נביא מקרבך מאחיך כמוני יקים לך ה' ותאמין בו כאשר אתה מאמין בי כי כן שאלת להיות דברי השם עמכם על ידי ושתשמעו אלי אם כן האמינו גם כן בשאר הנביאים הבאים אחרי כי כמוני כמוהם וזה טעם הטיבו אשר דברו להאמין בנביאי וכן אעשה להם לדורותם ויתכן שהיתה שאלתם שם לדורות וקבלתם שאמרו לשמוע ממשה באמרם "ואת תדבר אלינו ושמענו ועשינו" גם כן לדורות עולם ויהיה טעם "ואת" כמו ואתה וכל נביא השם כמוך כאשר פירשתי שם
@45 **ואשר ידבר בשם אלהים אחרים** . אפילו כיון את ההלכה לאסור את האסור ולהתיר את המותר ומת בחנק לשון רש"י מספרי (שופטים קעז קעח) ואין הענין לומר שאם בא אחד ואמר בחלומי ראיתי והנה פעור אומר לי שתזהרו במצות הלולב שיהא חייב מיתה כי זה פטור הוא ואם אומר שתעשו כן לעבוד לשקוץ ההוא אם כן זהו נביא השקר המתנבא לעבוד ע"ז ואפילו יאמר כן בשם השם הוא נסקל אבל הענין שיאמר ראיתי פעור כי הוא האלהים והוא מצוה שלא לאכול בשר חזיר וכן אם יגיד בשמו כי כזה וכזה עתיד להיות מאחר שיאמר כי הנעבד ההוא הוא האומר ועושה גוזר ומקיים יומת בחנק ולכך אמרו בגמרא (סנהדרין פט) המתנבא בשם ע"ז כגון נביאי הבעל והם שהיו אומרים שהבעל הוא האלהים כמו שכתוב (מלכים א יח כא) אם ה' הוא האלהים לכו אחריו ואם הבעל לכו אחריו והיו מתנבאים בו עלה והצלח ונתן ה' ביד המלך (שם כב טו) ודעתם לומר שהבעל הוא האדון אשר לו השם הנכבד הזה והוא שיתן רמות גלעד ביד אחאב
@46 **וכי תאמר בלבבך איכה נדע את הדבר אשר לא דברו ה'** . עתידים אתם לאמר כשיבוא חנניה בן עזור ומתנבא (ירמיהו כז טז) הנה כלי בית ה' מושבים מבבלה וירמיה עומד וצווח (שם פסוקים יט כב) על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה בבלה יובאו עם גלות צדקיהו לשון רש"י מספרי (שופטים קעח) והדרש הזה מפני שלא אמר "ואם תאמר בלבבך" והוא כמו שהזכרתי (לעיל ד כה) כי התורה תגיד ברמזים העתידות להיות אבל עיקר הכתוב לומר איכה נדע את הדבר אשר לא דברו השם שנהרוג המתנבא הזה וצוה כי כאשר לא יבוא הדבר אז יומת כי לא דברו השם ולא תגור ממנו מפני חכמתו או מפני האות שנתן ובא האות והמופת וכן היה להם לשאול איכה נדע הדבר אשר דברו ה' שנתחייב לשמוע אליו ככל אשר יצוה אבל זו תשובה לשתי השאלות כי בכל נביא נצפה לדבר העתיד להיות אשר יגיד ואם לא בא נדע שהוא נביא שקר ויומת ואם בא יבוא הכל הנה הוא נאמן לנביא לה' ונתחייב לשמוע אליו ככל אשר יצוה בשם ה' כמו שאמר (פסוק טו) "אליו תשמעון" ואפילו לעבור על דברי תורה לפי צורך השעה כגון אליהו בהר הכרמל וזה טעם "כמוני" "כמוך" שיהיה בתחילה נאמן לנביא השם או באות ומופת כענין שנאמר (שמות ד ל לא) ויעש האותות לעיני העם ויאמן העם או שיגיד העתיד להיות ויבוא שגם זה אות וכך אמרו במסכת סנהדרין (פט) והמוותר על דברי נביא מיתתו בידי שמים דכתיב אנכי אדרוש מעמו ואמרין (שם פט) ומנא ידע דאיענש דיהב ליה אות והא מיכה דלא יהב ליה אות ואיענש היכא דמוחזק שאני דאי לא תימא הכי אברהם בהר המוריה היכי שמע ליה יצחק אליהו בהר הכרמל היכי סמכינן עליה ועבדינן שחוטי חוץ אלא היכא דמוחזק שאני ורש"י כתב כבר נצטוו שאם בא להדיחך באחת מכל המצות לא תשמע לו אלא אם כן הוא מומחה לך שהוא צדיק גמור כגון אליהו בהר הכרמל לפי צורך השעה לכך נאמר אליו תשמעון וזה איננו נכון בעיני שאין ההמחאה שהוא צדיק גמור אלא שהוא נביא אמת מוחזק לכל במה שהקדים לאמר עתידות ובאו והוא האות שלו כמו שהזכיר בפרשה הזו או במופת שעשה בפנינו וזאת חזקת הנביאים ואולי נתכוון רש"י ב"צדיק גמור" למה שכתב הרב רבינו משה בהלכות יסודי התורה (פ"ז ה"ז) כשמשלחין את הנביא נותנין לו אות ומופת כדי שידעו העם שהאל שלחו באמת ולא כל העושה אות ומופת מאמינין אותו שהוא נביא אלא אדם שהיינו יודעים בו מתחילה שהוא ראוי לנבואה בחכמתו ובמעשיו שנתעלה בהן על כל בני גילו והיה מהלך בדרכי הנבואה ובקדושתה ופרישותה ואחר כך בא ועשה אות ומופת ואמר שהאל שלחו מצוה לשמוע ממנו שנאמר אליו תשמעון ואפשר שיעשה אות או מופת והוא אינו נביא וזה האות יש לו דברים בגו ואע"פ כן מצוה לשמוע לו הואיל ואדם גדול הוא וחכם וראוי לנבואה מעמידין אותו על חזקתו כמו שנצטוינו לחתוך הדין על פי שנים עדים כשרים ואע"פ שאפשר שהעידו שקר הואיל וכשרים הם אצלנו מעמידין אותם על כשרותן בדברים אלו וכיוצא בהם נאמר (להלן כט כח) הנסתרות לה' אלהינו ונאמר (שמואל א טז ז) האדם יראה לעינים וה' יראה ללבב
@48 **כי יכרית ה' אלהיך את הגוים וגו' שלוש ערים תבדיל לך** . גם זו מצוה מבוארת שכבר צוה בה (שמות כא יג) ועתה הוסיף לבאר משפטיה כי אמר וירשתם וישבת בעריהם ובבתיהם ללמד שלא נתחייבו בה אלא לאחר ירושה וישיבה וכן עשה יהושע והוסיף תכין לך הדרך שיהו סרטיאות מפורשות לתוכה ושיכתוב מקלט מקלט על פרשת הדרכים והוסיף ושלשת את גבול ארצך והוסיף עוד ללמדנו ענין השגגה כמו שאמר (פסוק ה) ואשר יבא את רעהו ביער וגו' ומדרשים רבים שדרשו רבותינו בפרשה
@55 **ואם ירחיב ה' אלהיך את גבלך** . הפרשה הזו עתידה וכבר הזכרתי מזה בפרשת ראה אנכי (לעיל יב כ) כי מתחילה אמר כי יכרית ה' אלהיך את הגוים אשר ה' אלהיך נותן לך את ארצם ו"הגויים אשר ה' אלהיך נותן לך את ארצם" ירמוז לכל השבעה אשר יזכיר בכל מקום וכן יאמר עליהם ונשל את הגוים האל מפניך (לעיל ז כב) וברשעת הגוים האלה (שם ט ד) והוריש ה' את כל הגוים האלה מלפניכם (שם יא כג) רק מערי העמים האלה (להלן כ טז) וכן במקומות רבים וצוה כי לאחר ירושה וישיבה בארצם יבדיל שלש ערים ובהם תשלום המצוה כמו שאמר (במדבר לה יג) שש ערי מקלט תהיינה לכם ואמר (שם פסוק יד) את שלש הערים תתנו מעבר לירדן ואת שלש הערים תתנו בארץ כנען ולא צוה בתורה ביותר משש הערים האלה וכן בכל מצות שבתורה הנוהגות לאחר ירושה וישיבה מתחייבין בהן לאחר ירושת שבעה גוים אלו אבל במצוה הזאת לבדה הוסיף בכאן ואם ירחיב ה' אלהיך את גבולך ולא אמר "כאשר דבר לך" כמו שאמר בכי ירחיב ה' אלהיך את גבולך של בשר תאוה (לעיל יב כ) כי ה' לא הבטיח אותם בשום מקום לתת להם רק שבעת הגוים האלה אבל הזכיר כאן האבות ואם ירחיב ה' אלהיך את גבולך כאשר נשבע לאבותיך ונתן לך את כל הארץ אשר דבר לתת לאבותיך וזה ירמוז לכל עשרה עממין שנאמרו לאברהם והתנה בזה כי תשמור את כל המצוה וגו' והנה דבר ברור הוא כי השבעה גוים עצמם לא יירשו אותם בעברם על התורה כאשר אמר פעמים רבים למען תחיו ובאתם וירשתם את הארץ (לעיל ד א) למען אשר תבא אל הארץ (להלן כז ג) כי אם שמור תשמרון את כל המצוה הזאת והוריש ה' את כל הגוים האלה מלפניכם (לעיל יא כב כג) וכאשר עבר עכן על החרם והוא איש אחד נאמר (יהושע ז יב) ולא יוכלו בני ישראל לקום לפני אויביהם ערף יפנו לפני אויביהם א"כ מה התנאי הזה אשר יתנה בשלשת העממין האלה לבדם ואם ירחיב ה' אלהיך את גבולך כי תשמר את כל המצוה וגו' והטעם בזה כי היה הרצון לפניו יתברך שינחיל אותם בימי משה ויהושע השבעה אשר הבטיחם במצרים ובמדבר כי היה גלוי לפניו שתגיע זכותם לכך ומפני זה חייב אותם בכל המצות בירושה של אלו וחייב אותם בשש ערי מקלט והבדילם יהושע אבל על השלשה הנשארים התנה כי תשמור את כל המצוה לאהבה את השם וללכת בדרכיו וגו' והוא לומר שיקיימו כולם כל התורה כולה ואין שום מצוה תלויה בכך זולתי שלש הערים האלה ומה טעם לאמר כי תשמור ללכת בדרכיו כל הימים תוסיף לך שלש הערים כי מי יודע מה יהיה אחרי כן כל הימים ואמר ר"א כל הימים בלי הפסק ביניהם ואיננו נכון אבל כי תשמר כאשר תגיע זכותך שתשמור כל המצוה לאהבה את השם אהבה שלימה קיימת לעולם שיהיה גלוי לפניו שלא תחטא עוד לעולם אז ירחיב את גבולך ויתן לך כל העמים והוא לימים אשר אמר (להלן ל ו) ומל ה' אלהיך את לבבך ואת לבב זרעך ו"לבב זרעך" יורה על כל הימים העתידים לבוא וכענין שנאמר בקבלה (ירמיה לב לט מ) ונתתי להם לב אחד ודרך אחד ליראה אותי כל הימים לטוב להם ולבניהם אחריהם וכרתי להם ברית עולם אשר לא אשוב מאחריהם להיטיבי אותם ואת יראתי אתן בלבבם לבלתי סור מעלי ואז כאשר יכרות להם ברית עולם יבדילו שלש הערים האלה
@60 **לא תחוס עינך עליו** . שלא תאמר הראשון כבר נהרג למה אנו הורגין את זה ונמצאו שנים הרוגין לשון רש"י מספרי (שופטים קפז) והטעם שלא תאמר כאשר נחוס על דם ההרוג טוב שנחוס על דם החי והנכון כי הכתוב יצוה בחייבי המיתות ובערת הרע מקרבך והיא מצות עשה אבל במרובי התקלות יזהיר עוד במצות לא תעשה שלא ינצלו מידינו לא מפני מוראם ולא שניתן להם רחמים וכך הזכיר במסית (לעיל יג ט) ואמר מכשפה לא תחיה (שמות כב יז) מפני היותה רבת המהומה המוכרת רבים בכשפיה וקצותה את כפה לא תחוס עינך (להלן כה יב) מפני כי הפתאים יהללו אותה בהיותה עוזרת לבעלה או מפני שהבושת מצוי ואין בו חסרון כיס וכן בעדים זוממין צוה (להלן פסוק כא) שלא ירחמו עליהם בעבור שלא נעשה בעדותם דבר או מפני שתקלתם מרובה וטעם וטוב לך כי ביעור הדם הנקי מצוה וטובה גדולה לך להציל ממות נפשך כי הרחמנות על הרוצחים שפיכות דמים מידי הרוצחים ומידי אחרים המתפרצים
@61 **לא תסיג גבול רעך** . אזהרה שלא ישנה תחום החלוקה שחלקו הנשיאים את הארץ לשבטים או ליחיד מהם ועל כן אמר אשר גבלו ראשונים הם אלעזר הכהן ויהושע בן נון ונשיאי המטות ולכך הזכיר בנחלתך אשר תנחל וגו' וטעם המצוה הזאת שלא יחשוב אדם לומר אין חלקי אשר נתנו לי שוה כמו חלק חברי כי טעו החולקים או שיוציא בלבו לעז על הגורלות ולא יהיה זה בעיניו גזל כלל על כן צוה בכאן שלא יחלוק אדם על החלוקה ההיא ולא ישנה הגבולין כלל לא בסתר ולא בגלוי וזו מצוה מבוארת ממה שצוה (במדבר כו נו) על פי הגורל תחלק נחלתו בין רב למעט ואמר (שם לד יז) אלה שמות האנשים אשר ינחלו לכם וגו' ועל דעת רבותינו (ספרי שופטים קפח) שהוא אזהרה לעוקר תחומו של חבירו בארץ שעובר בשני לאוין יהיה טעם "אשר גבלו ראשונים" שלא ישנה התחום הישן בסתר ויאמר בכאן היה מעולם והזהיר הכתוב בהווה כי התחום החדש ניכר וידוע הוא ואין אדם משנה אותו וגם רבותינו עצמם הזכירו (שם) מנין לעוקר תחומין של שבטים שעובר בלא תעשה תלמוד לומר לא תסיג גבול רעך והוא באמת פשוטו של מקרא
@65 **ודרשו השפטים היטב והנה עד שקר העד** . לא פירש הכתוב איך יודע שהוא עד שקר כי בהיות הענין בשני עדים שמעידין על הדבר אפילו יבואו מאה ויכחישו אותם לא יתברר ששקר ענו ולא נוכל לומר שבא הרוג ברגליו כי לא יאמר בזה ודרשו השופטים היטב ועל כן באה הקבלה הנאמנת ופירשה כי ההזמה תהיה כשיאמרו והלא ביום פלוני עמנו הייתם (מכות ה) והטעם מפני שהעדות הזו היא על גופם של עדים והם אינם נאמנים על עצמם לומר לא עשינו כך שהרי יכולים הללו לומר עליהם שהרגו את הנפש או שחללו את השבת
@66 **כאשר זמם** . ולא כאשר עשה מכאן אמרו הרגו אין נהרגין לשון רש"י מדברי רבותינו (מכות ה) והטעם בזה בעבור כי משפט העדים הזוממין בגזרת השליט שהם שנים ושנים והנה כאשר יבואו שנים ויעידו על ראובן שהרג את הנפש ויבואו שנים אחרים ויזימו אותם מעדותם צוה הכתוב שיהרגו כי בזכותו של ראובן שהיה נקי וצדיק בא המעשה הזה אילו היה רשע בן מות לא הצילו השם מיד ב"ד כאשר אמר (שמות כג ז) כי לא אצדיק רשע אבל אם נהרג ראובן נחשוב שהיה אמת כל אשר העידו עליו הראשונים כי הוא בעונו מת ואילו היה צדיק לא יעזבנו ה' בידם כמו שאמר הכתוב (תהלים לז לג) ה' לא יעזבנו בידו ולא ירשיענו בהשפטו ועוד שלא יתן ה' השופטים הצדיקים העומדים לפניו לשפוך דם נקי כי המשפט לאלהים הוא ובקרב אלהים ישפוט והנה כל זה מעלה גדולה בשופטי ישראל וההבטחה שהקב"ה מסכים על ידם ועמהם בדבר המשפט וזה טעם ועמדו שני האנשים אשר להם הריב לפני ה' (פסוק יז) כי לפני ה' הם עומדים בבואם לפני הכהנים והשופטים והוא ינחם בדרך אמת וכבר הזכרתי מזה בסדר ואלה המשפטים (שמות כא ו)
@69 **כי תצא למלחמה וגו' וראית סוס ורכב וגו'** . זו מצוה מחודשת אמרה להם עתה בבואם במלחמות וטעם כי ה' אלהיכם ההלך עמכם להלחם לכם עם איביכם להושיע אתכם יזהירם שלא ירך לבבם ולא ייראו מן האויבים ויאמר שלא יבטחו בזה בגבורתם לחשוב בלבם גבורים אנחנו ואנשי חיל למלחמה רק שישיבו לבם אל השם ויבטחו בישועתו ויחשבו כי לא בגבורת הסוס יחפץ ולא בשוקי האיש ירצה כי רוצה ה' את יראיו את המיחלים לחסדו ואמר להלחם לכם עם אויביכם כי יפילם לפניכם לחרב ואמר להושיע אתכם שהם ינצלו במלחמה ולא יפקד מהם איש כי יתכן שינצחו את אויביהם וימותו גם מהם רבים כדרך המלחמות ועל כן צעק יהושע בנפול מהם בעי כשלשים וששה איש (יהושע ז ז-ט) כי במלחמת מצוה שלו לא היה ראוי שיפול משערת ראשם ארצה כי לה' המלחמה והנה הכהן שהוא העובד את השם יזהירם ביראתו ויבטיחם אבל השוטרים ידברו בנוהג שבעולם פן ימות במלחמה כי בדרך הארץ בכל המלחמות ימותו אנשים גם מכת הנוצחים וצוה על השלשה האלה לשוב כי לבו על ביתו וכרמו ועל אשתו וינוס
@74 **וטעם ולא חללו** . שלא באה השנה הרביעית כי המנהג בכרם בבוא תבואתו שיחולו שם וילכו בו בחלילים וצוה הכתוב (ויקרא יט כד) שיהיה כל פריו קדש הלולים שיהללו את השם הנכבד בשמחה ההיא ויתכן שיהיה פירוש "ולא חללו" שלא עשאו חולין והוא הפדיון שהזכירו רבותינו (מעשר שני פ"ה מ"ד) מלשון כי חילל יהודה קודש ה' (מלאכי ב יא) ולא יחלל זרעו (ויקרא כא טו)
@76 **ויספו השטרים לדבר אל העם ואמרו מי האיש הירא** . על דעת רבי יוסי הגלילי (סוטה מד) כאשר הבטיח הכהן שהשם יושיעם ולא יפקד מהם איש ראוי שיבטחו בו הצדיקים ויזהירו השוטרים את היראים מעבירות שבידם ולכך תלתה לו התורה לחזור על ביתו וכרמו ואשתו לכסות על האחרים שחוזרין בשביל העבירות ויהיה טעם "פן ימות" שהוא יחשוב בלבו כן וינוס ועל דעת רבי עקיבא הוא כמשמעו כי מי שירא אחר הבטחת הכהן איננו בוטח בה' כראוי ולא יעשה לו הנס וטעם "ורך הלבב" שאינו בטבעו לראות מכת חרב והרג כי "הירא" הוא אשר לא יבטח ויחזיר אותו מפני מיעוט בטחונו ו"רך הלבב" מפני חולש טבעו כי ינוס או יתעלף ואמרו בירושלמי (סוטה פ"ח ה"ט) שכולם צריכים להביא ראיה לדבריהם כלומר שיביאו עדים על הבית ועל הכרם והאשה לפני שר הצבא ואז יתן לו רשות לחזור וכן אמרו גם לדעת רבי יוסי הגלילי שצריך להביא ראיה על העבירה שבידו ולולי כן היו מרבית העם חוזרים בטענות שקר אבל לדברי רבי עקיבא ברכות הלב שאיננו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה אמר שאין צריך להביא ראיה שעדיו עמו
@76 "ולא ימס את לבב אחיו" - עשאו בעל הלכות גדולות מצות לא תעשה שלא ימנע מלשוב שלא ימס את לבב אחיו כלבבו והוא כדרך ולא יאכל את בשרו (שמות כא כח)
@77 **ופקדו שרי צבאות בראש העם** . כי התורה תצוה בדרך הארץ ותעשה הנסים עם יראיו בהסתר ואין החפץ לפניו לשנות טבעו של עולם זולתי כאשר אין שם דרך בהצלה אחרת או להודיע שמו לצריו לעתים כאשר היה בקריעת ים סוף וכיוצא בו
@78 **כי תקרב אל עיר להלחם עליה וגו'** . במלחמת הרשות הכתוב מדבר כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחוקות ממך מאד לשון רש"י כתב הרב זה מספרי (שופטים קצט) ששנו שם כלשון הזה במלחמת הרשות הכתוב מדבר והכונה לרבותינו בכתוב הזה אינה אלא לומר שהפרשה בסופה תחלק בין שתי המלחמות אבל קריאת השלום אפילו במלחמת מצוה היא שחייבים לקרא לשלום אפילו לשבעה עממים שהרי משה קרא לשלום לסיחון מלך האמורי ולא היה עובר על עשה ועל לא תעשה שבפרשה כי החרם תחרימם (פסוק יז) ולא תחיה כל נשמה (פסוק טז) אבל הפרש שביניהם כאשר לא תשלים ועשתה מלחמה שצוה הכתוב ברחוקות להכות את כל זכורה ולהחיות להם הנשים והטף בזכרים ובערי העמים האלה צוה להחרים גם הנשים והטף וכך אמרו רבותינו במדרש אלה הדברים רבה (ה יג) והוא עוד בתנחומא ובגמרא ירושלמי (שביעית פ"ו ה"א) אמר רבי שמואל ברבי נחמני יהושע בן נון קיים הפרשה הזו מה עשה יהושע היה שולח פרוסדיטגמא בכל מקום שהיה הולך לכבוש והיה כותב בה מי שמבקש להשלים יבוא וישלים ומי שמבקש לילך לו ילך לו ומי שמבקש לעשות מלחמה יעשה מלחמה הגרגשי פנה הגבעונים שהשלימו עשה להם יהושע שלום שלשים ואחד מלכים שבאו להלחם הפילם הקב"ה וכו' וכך אמר הכתוב בכולם (יהושע יא יט כ) לא היתה עיר אשר השלימה אל בני ישראל בלתי החוי יושבי גבעון את הכל לקחו במלחמה כי מאת ה' היתה לחזק את לבם לקראת המלחמה את ישראל למען החרימם מכלל שאם רצו להשלים היו משלימים עמם ונראה שיש הפרש עוד בשאלת השלום שבערים הרחוקות נשאל להם לשלום ושיהיו לנו למס ויעבדונו אבל בערי (הערים) העמים האלה נשאל להם לשלום ומסים ועבדות על מנת שיקבלו עליהם שלא לעבוד ע"ז ולא הזכיר הכתוב זה בפרשה הזאת שכבר נאסר לנו בעובדי ע"ז (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי כי תעבוד את אלהיהם ויתכן שלא נצטרך להודיע להם רק השלום והמסים והשעבוד ואחרי שיהיו משועבדים לנו נגיד להם שאנו עושים משפטים בע"ז ובעובדיה בין יחיד בין רבים וכן מה שנאמר כאן (פסוק יח) למען אשר לא ילמדו אתכם לעשות ככל תועבותם ואמרו בספרי (שופטים רב) הא אם עשו תשובה אינן נהרגים בשבעת עממים הוא והתשובה הוא שיקבלו עליהם שבע מצות שנצטוו בני נח לא שיתגיירו להיותם גרי צדק ובמסכת סוטה אמרו (לה) שכתבו התורה על האבנים בשבעים לשון וכתבו למטה למען אשר לא ילמדו אתכם לעשות הא אם עשו תשובה מקבלים אותם ורש"י פירש שם להודיע לאומות היושבים חוץ מגבולם של ארץ ישראל שלא נצטוו להחרימם אלא על אותן שבתוך הגבולים כדי שלא ילמדו אותם מעשה קלקולם אבל אותם היושבים חוצה לה אומרים להם אם אתם חוזרים בתשובה נקבל אתכם ושבתוכה אין מקבלין אותם שמחמת יראה הם עושים וזה לשון הרב ואינו נכון כי בערי העמים האלה אשר ה' אלהיך נותן לך נחלה בהם אמר "למען אשר לא ילמדו אתכם" שאם עשו תשובה אינן נהרגין וכן אמר בהם (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי כי תעבד את אלהיהם הא אם עזבו את אלהיהם מותרין לישב שם וזה הענין שעשה המלך שלמה שכתוב בו (מלכים א ט טו-כב) וזה דבר המס אשר העלה המלך שלמה לבנות את בית ה' ואת ביתו ואת המלוא ואת חומת ירושלים וגו' כל העם הנותר מן האמורי החתי הפרזי החוי והיבוסי בניהם אשר נותרו אחריהם בארץ אשר לא יכלו בני ישראל להחרימם ויעלם שלמה למס עובד עד היום הזה ומבני ישראל לא נתן שלמה עבד והענין הזה כתורה עשאו כי קבלו עליהם שבע מצות ודבר ברור הוא כי כיון שנתנם שלמה עושי מלאכתו גברה ידו עליהם ויכול היה להחרימם אלא שהיה מותר לקיימם כמו שכתבנו
@79 **למס ועבדוך** . עד שיקבלו עליהם מסים ושעבוד לשון רבינו שלמה ובספרי (שופטים ר) אמרו מקבלין אנו עלינו מסים ולא שעבוד שעבוד ולא מסים אין שומעין להם עד שיקבלו עליהם זו וזו וענין המסים שיעלה עליהם מלך ישראל או הסנהדרין מס לבנות בית למלך וערי המסכנות אשר לו וכן לבנין בית השם והשעבוד הוא שיוכל כל איש מישראל ליקח מהם לחטוב עציו ולשאוב מימיו ונותן לו שכר הראוי וזה טעם "למס עובד" הכתוב בשלמה (מלכים א ט כא) שקבלו עליהם מסים ועבדות כדין התורה לא כענין שכתוב (שופטים א כח) ויהי כי חזק ישראל וישם את הכנעני למס והורש לא הורישו כי שם איננו מזכיר עבדות אבל כמלך שנותן שוחד למלך תקיף ממנו שלא ילחם בו ודע כי ענין אנשי גבעון היה מפני שלא היו יודעין משפטם של ישראל בקריאת השלום והקדימו קודם שתבא להם פרוסדיטגמא של יהושע ולכך אמרו (יהושע ט כד) ונירא מאד לנפשותינו או שלא רצו מתחילה לשמוע לדברי יהושע ובסוף פחדו ועשו עצמם נכרים דכתיב (שם פסוקים ג ד) ויושבי גבעון שמעו את אשר עשה יהושע ליריחו ולעי ויעשו גם המה בערמה והיה מועיל להם עוד שלא יהיו להם לעבדים אלא יהיו עמם בעלי ברית ומפני זה הקפידו עליהם והיו נהרגין אלמלא שבועת הנשיאים מפני שהיה עליהם לקבל מסים ושעבוד כמו שאמרנו והם כרתו להם ברית להיותם שוים להם ובעלי ברית ועוזרים זה לזה במלחמותיהם ועשו עמהם שלום לפי שהיו סבורין שהם ערים רחוקות מאד מן העמים שאין דעתם לבא עליהם כלל ולפיכך קלל אותם יהושע ואמר (שם פסוק כג) ועתה ארורים אתם שהם מן העמים הארורים אשר אררם ה' ועשה להם כמשפט הראוי להעשות בהם לקיים מה שנאמר למס ועבדוך שיהיו חוטבי עצים ושואבי מים לעדה ולמזבח ה' והוא המס והשעבוד כמו שפירשנו ויש אומרים כי פירוש והיה אם שלום תענך בעת הקריאה אבל אם מאנו מתחילה שוב אין מקבלין אותם והגבעונים מאנו בפרוסדיטגמא ולא היה הדין לקבלם והרב רבי משה כתב (הל' מלכים פ"ו ה"ה) שהקפידו עליהם מפני שכרתו להם ברית והרי הוא אומר (שמות כג לב) לא תכרות להם ולאלהיהם ברית ואינו נכון בעיני כי הגבעונים בודאי קבלו עליהם שלא לעבוד ע"ז כמו שאמרו (יהושע ט ט) באו עבדיך לשם ה' אלהיך ולכך לא הוצרך יהושע אחרי כן לומר להם שיקבלו עליהם לעבוד את השם כיון שכן מותרין היו בברית ההוא כמו שהיו מותרין בישיבת הארץ ששתיהן לא נאסרו אלא קודם התשובה כמו שאמר (שמות כג לג) פן יחטיאו אותך לי וכן אמר לא תכרות להם ולאלהיהם ברית אבל הדבר כמו שאמרנו
@86 **וטעם אשר לא ילמדו אתכם לעשות ככל תועבתם אשר עשו לאלהיהם** . שילמדו אתכם לעבוד השם הנכבד בשריפת בניכם ובנותיכם וכל תועבת ה' אשר שנא וחטאתם לה' אלהיכם שהוא הזהיר אתכם שלא תאמר איכה יעבדו הגוים האלה את אלהיהם ואעשה כן גם אני (לעיל יב ל) והנה התורה הזהירה (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי כי תעבוד את אלהיהם כי יהיה לך למוקש והיא אזהרה בעובדי כוכבים כי אם תכרות להם ולאלהיהם ברית ישבו בארצך ורבים מהם יפתוך לעבוד ע"ז וכאן הוסיף לבאר שלא תחיה כל נשמה כי אפילו היחיד הנשאר ביניכם לעבוד לך יזכיר לך עבודתם לאלהיהם ואולי תתפתה אתה לעשות כן לשם הנכבד ותחטא לפניו יתברך
@87 **כי האדם עץ השדה** . יפה פירש רבי אברהם כי שיעור הכתוב כי ממנו תאכל כי האדם עץ השדה ואותו לא תכרות לבא מפניך במצור וטעם כי האדם עץ השדה כמו כי נפש הוא חובל (להלן כד ו) אבל על דעת רבותינו (ב"ק צא) מותר לכרות עץ מאכל לבנות מצור ולא אמרה תורה רק עץ אשר תדע כי לא עץ מאכל הוא וגו' אלא להקדים ולומר שאילן סרק קודם לאילן מאכל אם כן פירוש הפרשה לדעתם שהזהירה תורה לא תשחית את עצה לכרות אותם דרך השחתה שלא לצורך המצור כמנהג המחנות והטעם כי הנלחמים משחיתים בעיר וסביב הארץ אולי יוכלו לה כענין שנאמר (מלכים ב ג יט) וכל עץ טוב תפילו וכל מעיני מים תסתמו ואתם לא תעשו כן להשחיתה כי תבטחו בשם שיתן אותה בידכם כי האדם עץ השדה הוא ממנו תאכל ותחיה ובו תבוא העיר מפניך במצור לומר אתה תחיה ממנו אחרי שתכבוש העיר וגם בהיותך במחנה לבא מפניך במצור תעשה כן וטעם אותו תשחית וכרת כי מותר אתה לכרות אותו לבנות המצור וגם להשחיתו עד רדתה כי לפעמים תהיה ההשחתה צורך הכבוש כגון שיהו אנשי העיר יוצאים ומלקטין עצים ממנו או נחבאים שם ביער להלחם בכם או שהם לעיר למחסה ולמסתור מאבן נגף
@92 **אל נחל איתן** . קשה שלא נעבד לשון רש"י ורבותינו אמרו (סוטה מו) שהוא נאסר לחרוש ולזרוע בו לעולם אם כן הן אזהרות שהזורע או העובד בו עובר בלאו הזה והטעם אשר יוציאו אותו אל נחל איתן כי לא יעבד בו ולא יזרע לעולם וטעם ונגשו הכהנים בני לוי לאמר כפר לעמך ישראל אשר פדית (פסוק ח) ושיעור הכתובים ונגשו הכהנים בני לוי וכל זקני העיר ההיא הקרובים אל החלל ירחצו את ידיהם וענו ואמרו והרחיצה במקצת מן הנזכרים והעניה במקצתם כדרך ואכלת לפני ה' אלהיך מעשר דגנך תירושך ויצהרך וגו' (לעיל יד כג) וענין העריפה אמר ר"א שהשם צוה לעשות כן על העיר הקרובה כי לולי שעשו עבירה כדומה לה לא נזדמן שיהרג אדם קרוב מהם ומחשבות ה' עמקו לאין קץ אצלנו אבל הרב אמר במורה הנבוכים (ג מ) כי הטעם לגלות על הרוצח ולבער דמו בעבור שברוב הפעמים יהיה הרוצח מן העיר אשר סביבות החלל וכשיצאו הזקנים ויתעסקו במדידה ההיא וזקני העיר ההיא יעידו לפני הבורא שלא התרשלו בתקון הדרכים ושמירתם ושאינם יודעים מי הרג את זה וכשיחקר הענין יאספו הזקנים ויביאו העגלה ירבו בני אדם לדבר בו אולי יגלה הדבר וכבר אמרו (ירושלמי סוטה פ"ט ה"א) שאפילו תבוא שפחה ותאמר פלוני הוא הרוצח לא תערף ואם יודע הרוצח ויחרישו ממנו ויעידו הבורא על נפשותם כי לא ידעוהו יהיה בזה זדון גדול וכל השומע שמץ דבר בענין יבוא ויגיד ויתפרסם הדבר ויהרג או על ידי ב"ד או המלך או גואל הדם ויתחזק הענין בהיות המקום אשר תערף בו העגלה לא יעבד בו ולא יזרע לעולם יכירו בו רואיו וידברו בו והנה לפי הטעם הזה יש בתחבולה הזו תועלת אבל המעשה איננו נרצה בעצמו והיה ראוי עוד שיעשה בשדה טוב ראוי לזריעה שיכירו בו רואיו כי בנחל איתן לא יודע מדוע לא יעבד בו ולפי דעתי יש בו טעם כענין הקרבנות הנעשים בחוץ שעיר המשתלח ופרה אדומה ולפיכך מנו חכמים עגלה ערופה מכלל החוקים
